/* Web版YTT 使い方の検索。webytt-materials/tools/build-guide.js が作る（手で直さない） */
window.YTT_SEARCH = [{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"sp-menu","n":"チャートをタップして出るメニュー","dv":"sp","k":"スマホ スマホの基本操作 ","w":"スマホでは、チャートを1回タップすると、丸いメニューが出ます。ここから時間足・十字カーソル・描画ツール・チャートの2つ表示に進めます。","t":"まわりの文字 （M1・M5・M15 … MN）：時間足を変える 十字のマーク ：十字カーソルを出す 「Z」のマーク ：描画ツールを出す 二重の四角のマーク ：チャートを2つ並べる メニューは、タップした場所に出ます","nr":"ちゃーとをたっぷしてでるめにゅー","kr":"すまほ すまほのきほんそうさ ","wr":"すまほでは、ちゃーとを1かいたっぷすると、まるいめにゅーがでます。ここからじかんあし・じゅうじかーそる・びょうがつーる・ちゃーとの2つひょうじにすすめます。","tr":"まわりのもじ （M1・M5・M15 … MN）：じかんあしをかえる じゅうじのまーく ：じゅうじかーそるをだす 「Z」のまーく ：びょうがつーるをだす にじゅうのしかくのまーく ：ちゃーとを2つならべる めにゅーは、たっぷしたばしょにでます"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"timeframe","n":"時間足を変える","dv":"sp","k":"スマホ スマホの基本操作 ","w":"ローソク足1本ぶんの時間（時間足）を切り替えます。M1（1分）から MN（1か月）まであり、短いほど細かく、長いほど大きな流れが見えます。","t":"チャートをタップして、丸いメニューを出す まわりに並ぶ M1・M5・M15 … から選ぶ いま見ている時間足は、チャートの左上（USDJPY・M15 のところ）と、メニューの色で分かります","nr":"じかんあしをかえる","kr":"すまほ すまほのきほんそうさ ","wr":"ろーそくあし1ほんぶんのじかん（じかんあし）をきりかえます。M1（1ふん）から MN（1かがつ）まであり、みじかいほどこまかく、ながいほどおおきなながれがみえます。","tr":"ちゃーとをたっぷして、まるいめにゅーをだす まわりにならぶ M1・M5・M15 … からえらぶ いまみているじかんあしは、ちゃーとのひだりうえ（USDJPY・M15 のところ）と、めにゅーのいろでわかります"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"pair","n":"通貨ペアを変える","dv":"sp","k":"スマホ スマホの基本操作 ","w":"表示する通貨ペア（USDJPY、GBPUSD など）を切り替えます。","t":"下のメニューの「通貨ペア」をタップ 一覧から、見たい通貨ペアを選ぶ チャートの左上の通貨ペア（BTCUSD・M15 のところ）をタップしても、同じ一覧が開きます チャートの下に並ぶミニチャートをタップしても切り替わります 一覧の ★ は、お気に入りに入れた通貨ペアです","nr":"つうかぺあをかえる","kr":"すまほ すまほのきほんそうさ ","wr":"ひょうじするつうかぺあ（USDJPY、GBPUSD など）をきりかえます。","tr":"したのめにゅーの「つうかぺあ」をたっぷ いちらんから、みたいつうかぺあをえらぶ ちゃーとのひだりうえのつうかぺあ（BTCUSD・M15 のところ）をたっぷしても、おなじいちらんがひらきます ちゃーとのしたにならぶみにちゃーとをたっぷしてもきりかわります いちらんの ★ は、おきにいりにいれたつうかぺあです"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"cursor","n":"十字カーソル","dv":"sp","k":"スマホ スマホの基本操作 ","w":"チャートの上で、価格と時間を十字の線で正確に合わせられるカーソルです。","t":"チャートをタップして、丸いメニューの 十字のマーク を選ぶ 指を動かして、見たい場所に合わせる ダブルタップ で終わる 色は「設定 → キャンバス」、スマホのカーソルの色は「設定 → 一般」の「カーソルカラー（スマホ）」で変えられます","nr":"じゅうじかーそる","kr":"すまほ すまほのきほんそうさ ","wr":"ちゃーとのうえで、かかくとじかんをじゅうじのせんでせいかくにあわせられるかーそるです。","tr":"ちゃーとをたっぷして、まるいめにゅーの じゅうじのまーく をえらぶ ゆびをうごかして、みたいばしょにあわせる だぶるたっぷ でおわる いろは「せってい → きゃんばす」、すまほのかーそるのいろは「せってい → いっぱん」の「かーそるからー（すまほ）」でかえられます"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"drawing","n":"描画ツール","dv":"sp","k":"スマホ スマホの基本操作 ","w":"水平線やトレンドライン、四角、テキスト、フィボナッチなどを、自分でチャートに引ける道具です。オートラインで足りないときに使います。","t":"チャートをタップして、丸いメニューの 「Z」のマーク を選ぶ 下に出た道具から、引きたいものを選ぶ チャートをなぞって引く 引いたあとに出る画面で、色と線の種類を選べます 色・太さ・線の種類は、道具ごとに、最後に使ったものが次も使われます 10番目の「一覧」で、すべての通貨ペアに引いた線や図形を一覧で見て、選んだり消したりできます（PCの 描画ツール に画像があります） 道具は左から10個。それぞれの意味は「もっとくわしく」を見てください アップデート予定 指で引くときに始点・終点が指で隠れないよう、十字カーソルで引けるようになります 下に出る道具は、左から順にこうなっています。 水平ライン ：まっすぐ横の線。支持線・抵抗線を引くときに レイ ：点から片側だけにのびる線 トレンドライン ：ななめの線 平行チャネル ：平行な2本の線。上下のはばを見るときに 垂直線 ：まっすぐ縦の線。時間の目印に 四角 ：はんいを囲む テキスト ：文字を書き込む フィボナッチ ：押し目・戻りの目安を出す 一覧 ：引いたものを見る・消す × ：道具をしまう","nr":"びょうがつーる","kr":"すまほ すまほのきほんそうさ ","wr":"すいへいせんやとれんどらいん、しかく、てきすと、ふぃぼなっちなどを、じぶんでちゃーとにひけるどうぐです。おーとらいんでたりないときにつかいます。","tr":"ちゃーとをたっぷして、まるいめにゅーの 「Z」のまーく をえらぶ したにでたどうぐから、ひきたいものをえらぶ ちゃーとをなぞってひく ひいたあとにでるがめんで、いろとせんのしゅるいをえらべます いろ・ふとさ・せんのしゅるいは、どうぐごとに、さいごにつかったものがつぎもつかわれます 10ばんめの「いちらん」で、すべてのつうかぺあにひいたせんやずけいをいちらんでみて、えらんだりけしたりできます（PCの びょうがつーる にがぞうがあります） どうぐはひだりから10こ。それぞれのいみは「もっとくわしく」をみてください あっぷでーとよてい ゆびでひくときにしてん・しゅうてんがゆびでかくれないよう、じゅうじかーそるでひけるようになります したにでるどうぐは、ひだりからじゅんにこうなっています。 すいへいらいん ：まっすぐよこのせん。しじせん・ていこうせんをひくときに れい ：つからかたがわだけにのびるせん とれんどらいん ：ななめのせん へいこうちゃねる ：へいこうな2ほんのせん。じょうげのはばをみるときに すいちょくせん ：まっすぐたてのせん。じかんのめじるしに しかく ：はんいをかこむ てきすと ：もじをかきこむ ふぃぼなっち ：おしめ・もどりのめやすをだす いちらん ：ひいたものをみる・けす × ：どうぐをしまう"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"split","n":"チャートを2つ並べる","dv":"sp","k":"スマホ スマホの基本操作 ","w":"画面を上下に分けて、チャートを2つ表示できます。別の通貨ペアや、別の時間足を同時に見たいときに使います。","t":"チャートをタップして、丸いメニューの 二重の四角のマーク を選ぶ 境目を長押しすると、それぞれの大きさを変えられる 下のチャートだけ、通貨ペアや時間足を変えることもできる 閉じるときは、 境目を長押し して、出てきた × を押します","nr":"ちゃーとを2つならべる","kr":"すまほ すまほのきほんそうさ ","wr":"がめんをじょうげにわけて、ちゃーとを2つひょうじできます。べつのつうかぺあや、べつのじかんあしをどうじにみたいときにつかいます。","tr":"ちゃーとをたっぷして、まるいめにゅーの にじゅうのしかくのまーく をえらぶ さかいめをなげししすると、それぞれのおおきさをかえられる したのちゃーとだけ、つうかぺあやじかんあしをかえることもできる とじるときは、 さかいめをなげしし して、でてきた × をおします"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"sp-screenshot","n":"スクリーンショット","dv":"sp","k":"スマホ スマホの基本操作 ","w":"いま見ているチャートを、画像として保存する機能です。トレードの記録を残したり、人に見せたりするときに使います。","t":"上の カメラ のボタンをタップ 「撮影範囲」を選ぶ 「撮影してダウンロード」をタップ 出てきた共有のメニューで「画像を保存」をタップ チャートエリア全体 ：並べて表示しているチャートを、まとめて1枚に 選択中のチャートのみ ：いま選んでいるチャート1つだけ 保存した画像は、写真アプリに入ります","nr":"すくりーんしょっと","kr":"すまほ すまほのきほんそうさ ","wr":"いまみているちゃーとを、がぞうとしてほぞんするきのうです。とれーどのきろくをのこしたり、にんにみせたりするときにつかいます。","tr":"うえの かめら のぼたんをたっぷ 「さつえいはんい」をえらぶ 「さつえいしてだうんろーど」をたっぷ でてきたきょうゆうのめにゅーで「がぞうをほぞん」をたっぷ ちゃーとえりあぜんたい ：なべてひょうじしているちゃーとを、まとめて1まいに せんたくちゅうのちゃーとのみ ：いまえらんでいるちゃーと1つだけ ほぞんしたがぞうは、しゃしんあぷりにいります"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"fullscreen","n":"全画面で見る","dv":"sp","k":"スマホ スマホの基本操作 ","w":"まわりのパネルを消して、チャートだけを画面いっぱいに表示します。","t":"チャートの右下にある2つのボタンのうち、 左のほう を押します（画像は、押して全画面にしたところ。もう一度押すと戻ります） もう一度押すと、元の画面に戻ります","nr":"ぜんがめんでみる","kr":"すまほ すまほのきほんそうさ ","wr":"まわりのぱねるをけして、ちゃーとだけをがめんいっぱいにひょうじします。","tr":"ちゃーとのみぎしたにある2つのぼたんのうち、 ひだりのほう をおします（がぞうは、おしてぜんがめんにしたところ。もういちどおすともどります） もういちどおすと、もとのがめんにもどります"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"sp-landscape","n":"横向きで使う","dv":"sp","k":"スマホ スマホの基本操作 ","w":"スマホは、縦向きでも横向きでも使えます。チャートを横に広く見たいときは、スマホを横向きにしてください。","t":"スマホの「画面の向きのロック」がオンだと、横にしても向きが変わりません アップデート予定 iPhoneを横向きにしたときに、うまく表示されないことがあります。アップデートで直ります","nr":"よこむききでつかう","kr":"すまほ すまほのきほんそうさ ","wr":"すまほは、たてむきでもよこむききでもつかえます。ちゃーとをよこにひろくみたいときは、すまほをよこむききにしてください。","tr":"すまほの「がめんのむきのろっく」がおんだと、よこにしてもむきがかわりません あっぷでーとよてい iPhoneをよこむききにしたときに、うまくひょうじされないことがあります。あっぷでーとでなおります"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"pc-pair","n":"通貨ペアを変える・お気に入り","dv":"pc","k":"PC PCの基本操作 ","w":"上のメニューの通貨ペアを押すと、一覧が開きます。よく見る通貨ペアに ★ を付けておくと、画面の下の帯に並んで、すぐに切り替えられます。","t":"上のメニューの通貨ペア（GBPUSD のところ）を押す 一覧で、よく見る通貨ペアの ★ を押す 画面の下の帯に並ぶので、そこから切り替える 一覧には、BID・ASK・24時間の変化率と、最近の動きの小さなチャートが出ます 下の帯は、ドラッグで順番を入れ替えられます ★は、少なくとも1つは残しておく必要があります ★をつけた通貨ペアは、PC・スマホのほかの端末にも引き継がれます アップデート予定 通貨ペアの一覧を、好きな順に並び替えられるようになります","nr":"つうかぺあをかえる・おきにいり","kr":"PC PCのきほんそうさ ","wr":"うえのめにゅーのつうかぺあをおすと、いちらんがひらきます。よくみるつうかぺあに ★ をつけておくと、がめんのしたのおびにならんで、すぐにきりかえられます。","tr":"うえのめにゅーのつうかぺあ（GBPUSD のところ）をおす いちらんで、よくみるつうかぺあの ★ をおす がめんのしたのおびにならぶので、そこからきりかえる いちらんには、BID・ASK・24じかんのへんかりつと、さいきんのうごきのちいさなちゃーとがでます したのおびは、どらっぐでじゅんばんをいれかえられます ★は、すくなくとも1つはのこしておくひつようがあります ★をつけたつうかぺあは、PC・すまほのほかのたんまつにもひきつがれます あっぷでーとよてい つうかぺあのいちらんを、すきなじゅんにならびかえられるようになります"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"pc-tf","n":"時間足を変える","dv":"pc","k":"PC PCの基本操作 ","w":"PCでは、画面の上のメニューに時間足が並びます。押すだけで切り替わります。","t":"M1・M5・M15・M30・H1・H4・D1・W1・MN の9つです いま選んでいる時間足には、色がつきます 左の名前（GBPUSD のところ）が通貨ペア、右に カメラ・ベル・ポジション・履歴 が並びます アップデート予定 時間足を変えても、いまの足が決めた位置（右端からの距離）に来るようになります","nr":"じかんあしをかえる","kr":"PC PCのきほんそうさ ","wr":"PCでは、がめんのうえのめにゅーにじかんあしがならびます。おすだけできりかわります。","tr":"M1・M5・M15・M30・H1・H4・D1・W1・MN の9つです いまえらんでいるじかんあしには、いろがつきます ひだりのなまえ（GBPUSD のところ）がつうかぺあ、みぎに かめら・べる・ぽじしょん・りれき がならびます あっぷでーとよてい じかんあしをかえても、いまのあしがきめたいち（みぎはしからのきょり）にくるようになります"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"pc-history","n":"トレード履歴","dv":"pc","k":"PC PCの基本操作 ","w":"これまでのトレードの一覧です。チケット番号・シナリオ・銘柄・方向・数量・エントリー価格・クローズ価格・日時・スワップ・手数料・損益が並びます。","t":"上のメニューの「履歴」か、その右の ▾ から開きます 入金・出金も同じ一覧に出ます","nr":"とれーどりれき","kr":"PC PCのきほんそうさ ","wr":"これまでのとれーどのいちらんです。ちけっとばんごう・しなりお・めいがら・ほうこう・すうりょう・えんとりーかかく・くろーずかかく・にちじ・すわっぷ・てすうりょう・そんえきがならびます。","tr":"うえのめにゅーの「りれき」か、そのみぎの ▾ からひらきます にゅうきん・しゅっきんもおなじいちらんにでます"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"pc-alert","n":"通知の履歴（ベル）","dv":"pc","k":"PC PCの基本操作 ","w":"上のメニューのベルを押すと、「アラート・エラー履歴」が開きます。通知ラインに価格が来たとき、エントリーや決済をしたとき、経済指標のアラームなどが、ここに並びます。","t":"「通知ラインを設置 価格到達で通知(0/10)」から、通知ラインを置けます（1つの口座につき10本まで。通貨ペアを分けても合わせて10本です。口座を切り替えれば、その口座でも10本置けます） 「下降転換」「上昇転換」では、何分足でトレンドが転換したときに通知するかを選びます（例：M5にしておくと、いま表示している通貨ペアのM5で転換したときに通知が来ます） 「下降転換」「上昇転換」は、押すたびに1件ずつ登録され、それぞれ5件まで置けます。1回通知すると終わるので、また使うときは置き直します 履歴には、最近の10件が残ります。同じお知らせが続くと「×2」のようにまとめて出ます","nr":"つうちのりれき（べる）","kr":"PC PCのきほんそうさ ","wr":"うえのめにゅーのべるをおすと、「あらーと・えらーりれき」がひらきます。つうちらいんにかかくがきたとき、えんとりーやけっさいをしたとき、けいざいしひょうのあらーむなどが、ここにならびます。","tr":"「つうちらいんをせっち かかくとうたつでつうち(0/10)」から、つうちらいんをおけます（1つのこうざにつき10ほんまで。つうかぺあをわけてもあわせて10ほんです。こうざをきりかえれば、そのこうざでも10ほんおけます） 「かこうてんかん」「じょうしょうてんかん」では、なんぷんあしでとれんどがてんかんしたときにつうちするかをえらびます（れい：M5にしておくと、いまひょうじしているつうかぺあのM5でてんかんしたときにつうちがきます） 「かこうてんかん」「じょうしょうてんかん」は、おすたびに1けんずつとうろくされ、それぞれ5けんまでおけます。1かいつうちするとおわるので、またつかうときはおきなおします りれきには、さいきんの10けんがのこります。おなじおしらせがつづくと「×2」のようにまとめてでます"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"pc-layout","n":"チャートの並べ方（レイアウト）","dv":"pc","k":"PC PCの基本操作 ","w":"チャートを1画面から4分割まで、好きな並びにできます。並びに名前を付けて保存しておくと、いつでも呼び出せます。","t":"上のメニューの □ のボタンを押す 「チャートの型」から並びを選ぶ 気に入った並びは、下の欄に名前を入れて「保存」 型は、1画面／左右2／上下2／横3／縦3／4分割 の6つです 保存した並びは「保存したレイアウト」に残り、押すだけで呼び出せます","nr":"ちゃーとのならべほう（れいあうと）","kr":"PC PCのきほんそうさ ","wr":"ちゃーとを1がめんから4ぶんかつまで、すきなならびにできます。ならびになまえをつけてほぞんしておくと、いつでもよびだせます。","tr":"うえのめにゅーの □ のぼたんをおす 「ちゃーとのかた」からならびをえらぶ きにいったならびは、したのらんになまえをいれて「ほぞん」 かたは、1がめん／さゆう2／じょうげ2／よこ3／たて3／4ぶんかつ の6つです ほぞんしたならびは「ほぞんしたれいあうと」にのこり、おすだけでよびだせます"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"screenshot","n":"スクリーンショット","dv":"pc","k":"PC PCの基本操作 ","w":"いま見ているチャートを、画像として保存する機能です。トレードの記録を残したり、人に見せたりするときに使います。","t":"上のメニューの カメラ のボタンを押す 「撮影範囲」を選ぶ 「撮影してダウンロード」を押す チャートエリア全体 ：並べて表示しているチャートを、まとめて1枚に 選択中のチャートのみ ：いま選んでいるチャート1つだけ 画像は、そのままパソコンに保存されます（ダウンロードのフォルダ）","nr":"すくりーんしょっと","kr":"PC PCのきほんそうさ ","wr":"いまみているちゃーとを、がぞうとしてほぞんするきのうです。とれーどのきろくをのこしたり、にんにみせたりするときにつかいます。","tr":"うえのめにゅーの かめら のぼたんをおす 「さつえいはんい」をえらぶ 「さつえいしてだうんろーど」をおす ちゃーとえりあぜんたい ：なべてひょうじしているちゃーとを、まとめて1まいに せんたくちゅうのちゃーとのみ ：いまえらんでいるちゃーと1つだけ がぞうは、そのままぱそこんにほぞんされます（だうんろーどのふぉるだ）"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"pc-draw","n":"描画ツール","dv":"pc","k":"PC PCの基本操作 ","w":"PCでは、チャートの左に描画の道具が縦に並びます。十字カーソルもここにあります。","t":"道具は上から10個です この列の右のふちを右にドラッグすると、ほかの通貨ペアの ミニチャート を出せます 色・太さ・線の種類は、道具ごとに、最後に使ったものが次も使われます いちばん下の「一覧」で、すべての通貨ペアに引いた線や図形を一覧で見て、選んだり消したりできます（「もっとくわしく」に画像があります） 上から順に、こうなっています。 十字カーソル ：価格と時間を正確に合わせる 水平ライン ：まっすぐ横の線。支持線・抵抗線を引くときに レイ ：点から片側だけにのびる線 トレンドライン ：ななめの線 平行線（チャネル） ：平行な2本の線 垂直線 ：まっすぐ縦の線。時間の目印に 四角 ：はんいを囲む テキスト ：文字を書き込む フィボナッチ ：押し目・戻りの目安を出す 一覧 ：引いたものを見る・消す 「一覧」を押すと、 オブジェクト一覧 が開きます。すべての通貨ペアに引いた線や図形が、通貨ペアと日時つきで並びます。押すとその図形が選ばれ、× で1つずつ、「すべて削除」でまとめて消せます。 PCの「オブジェクト一覧」 タップで拡大","nr":"びょうがつーる","kr":"PC PCのきほんそうさ ","wr":"PCでは、ちゃーとのひだりにびょうがのどうぐがたてにならびます。じゅうじかーそるもここにあります。","tr":"どうぐはうえから10こです このつらのみぎのふちをみぎにどらっぐすると、ほかのつうかぺあの みにちゃーと をだせます いろ・ふとさ・せんのしゅるいは、どうぐごとに、さいごにつかったものがつぎもつかわれます いちばんしたの「いちらん」で、すべてのつうかぺあにひいたせんやずけいをいちらんでみて、えらんだりけしたりできます（「もっとくわしく」にがぞうがあります） うえからじゅんに、こうなっています。 じゅうじかーそる ：かかくとじかんをせいかくにあわせる すいへいらいん ：まっすぐよこのせん。しじせん・ていこうせんをひくときに れい ：つからかたがわだけにのびるせん とれんどらいん ：ななめのせん へいこうせん（ちゃねる） ：へいこうな2ほんのせん すいちょくせん ：まっすぐたてのせん。じかんのめじるしに しかく ：はんいをかこむ てきすと ：もじをかきこむ ふぃぼなっち ：おしめ・もどりのめやすをだす いちらん ：ひいたものをみる・けす 「いちらん」をおすと、 おぶじぇくといちらん がひらきます。すべてのつうかぺあにひいたせんやずけいが、つうかぺあとにちじつきでならびます。おすとそのずけいがえらばれ、× で1つずつ、「すべてさくじょ」でまとめてけせます。 PCの「おぶじぇくといちらん」 たっぷでかくだい"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"minichart","n":"左のミニチャート","dv":"pc","k":"PC PCの基本操作  ミニチャート表示 表示","w":"チャートの左に、ほかの通貨ペアの動きを小さく並べておける画面です。メインのチャートを切り替えなくても、いまの値と、上がっているか下がっているかが分かります。","t":"左の描画ツールの 右のふち を、右にドラッグする 通貨ペアの名前・いまの値・▲▼ が、上下に並びます ふちを左に戻すと、しまえます PCは5つまで並びます（縦に入りきらないときは4つ）。スマホはチャートの下に3つで、PCの上から3つと同じ通貨ペアです 並んでいる枠や空いている枠を押すと、通貨ペアを選んで、その枠を入れ替えられます 並べた通貨ペアは、PCとスマホで同じになります 右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」 の「ミニチャート表示」で、表示する・しないを切り替えられます（最初はオン）","nr":"ひだりのみにちゃーと","kr":"PC PCのきほんそうさ  みにちゃーとひょうじ ひょうじ","wr":"ちゃーとのひだりに、ほかのつうかぺあのうごきをちーさくなべておけるがめんです。めいんのちゃーとをきりかえなくても、いまのあたいと、あがっているかさがっているかがわかります。","tr":"ひだりのびょうがつーるの みぎのふち を、みぎにどらっぐする つうかぺあのなまえ・いまのあたい・▲▼ が、じょうげにならびます ふちをひだりにもどすと、しまえます PCは5つまでならびます（たてにいりきらないときは4つ）。すまほはちゃーとのしたに3つで、PCのうえから3つとおなじつうかぺあです ならんでいるわくやあいているわくをおすと、つうかぺあをえらんで、そのわくをいれかえられます ならべたつうかぺあは、PCとすまほでおなじになります みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」 の「みにちゃーとひょうじ」で、ひょうじする・しないをきりかえられます（さいしょはおん）"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"pc-account","n":"口座を切り替える","dv":"pc","k":"PC PCの基本操作 ","w":"複数の口座をつないでいるとき、取引する口座を切り替えられます。","t":"残高の上にある口座番号を押す 一覧から、使う口座を選ぶ 「確定」を押す 切り替えると、残高や保有中のポジションも、その口座のものに変わります PCとスマホは、それぞれ別に口座を選びます（PCで切り替えても、スマホは元の口座のままです）","nr":"こうざをきりかえる","kr":"PC PCのきほんそうさ ","wr":"ふくすうのこうざをつないでいるとき、とりひきするこうざをきりかえられます。","tr":"ざんだかのうえにあるこうざばんごうをおす いちらんから、つかうこうざをえらぶ 「かくてい」をおす きりかえると、ざんだかやほゆうなかのぽじしょんも、そのこうざのものにかわります PCとすまほは、それぞれべつにこうざをえらびます（PCできりかえても、すまほはもとのこうざのままです）"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"shortcuts","n":"キーボードのショートカット","dv":"pc","k":"PC PCの基本操作 ","w":"PCでは、よく使う操作をキーボードだけで呼び出せます。設定を開かなくても、線を置いたり、チャートの表示を切り替えたりできます。","t":"注文や決済のショートカットはありません （押しまちがいで注文・決済されないようにするためです） スマホにはありません","nr":"きーぼーどのしょーとかっと","kr":"PC PCのきほんそうさ ","wr":"PCでは、よくつかうそうさをきーぼーどだけでよびだせます。せっていをひらかなくても、せんをおいたり、ちゃーとのひょうじをきりかえたりできます。","tr":"ちゅうもんやけっさいのしょーとかっとはありません （おしまちがいでちゅうもん・けっさいされないようにするためです） すまほにはありません"},{"f":"ytt-web-f-basic.html","pt":"基本の操作","no":"1","id":"push-notify","n":"スマホに通知を届ける設定","dv":"","k":"スマホとPC 通知を受け取る設定 ","w":"通知ライン に価格が来たとき、建値・トレイル・1/2決済の線に価格が来てSLが動いたり決済されたとき、経済指標・セッションのアラートは、連携EAを動かしているパソコンのMT4/MT5から、スマホのMT4/MT5アプリにプッシュ通知で届きます。受け取るには、はじめに一度だけ、上の手順で設定します（画像はMT5の画面です。MT4も同じ流れです）。","t":"アップデート予定 通知のたびに、パソコンのMT4/MT5でも音つきのアラートが鳴るようになります（最初はオン。設定で切り替えられます） パソコンのブラウザには、通知は出ません PCは、上のメニューのベルで、通知の履歴も見られます（ 通知の履歴（ベル） ）","nr":"すまほにつうちをとどけるせってい","kr":"すまほとPC つうちをうけとるせってい ","wr":"つうちらいん にかかくがきたとき、たてね・とれいる・1/2けっさいのせんにかかくがきてSLがうごいたりけっさいされたとき、けいざいしひょう・せっしょんのあらーとは、れんけいEAをうごかしているぱそこんのMT4/MT5から、すまほのMT4/MT5あぷりにぷっしゅつうちでとどきます。うけとるには、はじめにいちどだけ、うえのてじゅんでせっていします（がぞうはMT5のがめんです。MT4もおなじながれです）。","tr":"あっぷでーとよてい つうちのたびに、ぱそこんのMT4/MT5でもおとつきのあらーとがなるようになります（さいしょはおん。せっていできりかえられます） ぱそこんのぶらうざには、つうちはでません PCは、うえのめにゅーのべるで、つうちのりれきもみられます（ つうちのりれき（べる） ）"},{"f":"ytt-web-f-trade.html","pt":"注文・ロット・決済","no":"2","id":"order","n":"成行注文","dv":"","k":"注文と決済 注文と決済 ","w":"いまの価格で、すぐに売買する注文です。ロット（注文の量）を決めて、買いなら「BUY」、売りなら「SELL」を押すだけでエントリーできます。","t":"「成行」を開く（PCは右のパネル、スマホは右上のボタン） ロットを決める（PCは数字を打ち込むか、下の ±0.01〜1 のボタン。スマホは ∧ ∨ のボタンか、数字をタップして入力） 買いなら「BUY」、売りなら「SELL」を押す 確認の画面が出たら、赤い（青い）ボタンで発注する LOTの欄の数字が、そのまま注文されるロットです iPhoneでキーボードが出ないときは、ロットの数字をタップして選んだあと、そこを少し長押しするようにしっかり触ると出てきます 確認の画面には、方向・数量・SLまでの幅・想定損失が出ます。 押した瞬間に約定し、取り消せません 確認の画面を出さずに、押した瞬間に発注することもできます（右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「決済関連」 の「成行エントリーで確認」をオフ） ロットは「 ロットの決め方 」の設定で、自動で計算させることもできます 持ったポジションは「全決済」「1/2決済」か、下のメニューの「ポジション」の一覧にある「決済」で決済できます この注文でつくのはSLだけで、TPはつきません（RR比固定がオンのときを除く）。TPも置きたいときは「 シナリオ 」を使います","nr":"なりゆきちゅうもん","kr":"ちゅうもんとけっさい ちゅうもんとけっさい ","wr":"いまのかかくで、すぐにばいばいするちゅうもんです。ろっと（ちゅうもんのりょう）をきめて、かいなら「BUY」、うりなら「SELL」をおすだけでえんとりーできます。","tr":"「なりゆき」をひらく（PCはみぎのぱねる、すまほはみぎうえのぼたん） ろっとをきめる（PCはすうじをうちこむか、したの ±0.01〜1 のぼたん。すまほは ∧ ∨ のぼたんか、すうじをたっぷしてにゅうりょく） かいなら「BUY」、うりなら「SELL」をおす かくにんのがめんがでたら、あかい（あおい）ぼたんではっちゅうする LOTのらんのすうじが、そのままちゅうもんされるろっとです iPhoneできーぼーどがでないときは、ろっとのすうじをたっぷしてえらんだあと、そこをすこしなげししするようにしっかりふるとでてきます かくにんのがめんには、ほうこう・すうりょう・SLまでのはば・そうていそんしつがでます。 おしたしゅんかんにやくじょうし、とりけせません かくにんのがめんをださずに、おしたしゅんかんにはっちゅうすることもできます（みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「けっさいかんれん」 の「なりゆきえんとりーでかくにん」をおふ） ろっとは「 ろっとのきめかた 」のせっていで、じどうでけいさんさせることもできます もったぽじしょんは「ぜんけっさい」「1/2けっさい」か、したのめにゅーの「ぽじしょん」のいちらんにある「けっさい」でけっさいできます このちゅうもんでつくのはSLだけで、TPはつきません（RRひこていがおんのときをのぞく）。TPもおきたいときは「 しなりお 」をつかいます"},{"f":"ytt-web-f-trade.html","pt":"注文・ロット・決済","no":"2","id":"close","n":"全決済・1/2決済","dv":"","k":"注文と決済 注文と決済 ","w":"持っているポジションを決済する（利益や損失を確定させる）ボタンです。「全決済」はまとめて、「1/2決済」は半分だけ決済します。","t":"全決済 ：保有中のポジションをすべて決済します。ポジションが1つでも複数でも使えます 1/2決済 ：ロットの半分だけ決済します。もう一度押すと、残りのさらに半分を決済します（例：1lot → 0.5lot → 0.25lot） ボタンの場所：PCは右のパネルの「成行」、スマホはチャートの下","nr":"ぜんけっさい・1/2けっさい","kr":"ちゅうもんとけっさい ちゅうもんとけっさい ","wr":"もっているぽじしょんをけっさいする（りえきやそんしつをかくていさせる）ぼたんです。「ぜんけっさい」はまとめて、「1/2けっさい」ははんぶんだけけっさいします。","tr":"ぜんけっさい ：ほゆうなかのぽじしょんをすべてけっさいします。ぽじしょんが1つでもふくすうでもつかえます 1/2けっさい ：ろっとのはんぶんだけけっさいします。もういちどおすと、のこりのさらにはんぶんをけっさいします（れい：1lot → 0.5lot → 0.25lot） ぼたんのばしょ：PCはみぎのぱねるの「なりゆき」、すまほはちゃーとのした"},{"f":"ytt-web-f-trade.html","pt":"注文・ロット・決済","no":"2","id":"positions","n":"ポジションと履歴","dv":"","k":"注文と決済 注文と決済 ","w":"いま持っているポジション（保有中の注文）と、これまでに決済したトレードを、一覧で見られる画面です。","t":"開き方：PCは上のメニュー、スマホは下のメニューの「ポジション」「履歴」 ボタンの横の数字は、保有中のポジションの数と、履歴の件数です ポジションは、1件ずつ「決済」ボタンで決済できます 履歴には、口座への入金も並びます","nr":"ぽじしょんとりれき","kr":"ちゅうもんとけっさい ちゅうもんとけっさい ","wr":"いまもっているぽじしょん（ほゆうなかのちゅうもん）と、これまでにけっさいしたとれーどを、いちらんでみられるがめんです。","tr":"ひらきほう：PCはうえのめにゅー、すまほはしたのめにゅーの「ぽじしょん」「りれき」 ぼたんのよこのすうじは、ほゆうなかのぽじしょんのかずと、りれきのけんすうです ぽじしょんは、1けんずつ「けっさい」ぼたんでけっさいできます りれきには、こうざへのにゅうきんもならびます"},{"f":"ytt-web-f-trade.html","pt":"注文・ロット・決済","no":"2","id":"settle","n":"決済まわりの設定","dv":"","k":"注文と決済 注文と決済  成行エントリーで確認 決済関連 ワンクリック決済 決済関連 全決済時に表示中の通貨ペアのみ決済 決済関連","w":"注文や決済のボタンを押したときに、確認の画面を出すかどうかを決める設定です。押し間違いを防ぎたいか、すばやく操作したいかで選びます。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「決済関連」を開く 使いたい項目にチェックを入れる 成行エントリーで確認 ：SELL / BUY を押したあとに確認が出ます。オフにすると、押した瞬間に発注します ワンクリック決済 ：オンにすると、確認なしですぐに決済します 全決済時に表示中の通貨ペアのみ決済 ：オンにすると、全決済でいま表示している通貨ペアのポジションだけを決済します ご注意 押し間違いを防ぐため、慣れるまでは「成行エントリーで確認」をオンのまま使うのがおすすめです。","nr":"けっさいまわりのせってい","kr":"ちゅうもんとけっさい ちゅうもんとけっさい  なりゆきえんとりーでかくにん けっさいかんれん わんくりっくけっさい けっさいかんれん ぜんけっさいときにひょうじちゅうのつうかぺあのみけっさい けっさいかんれん","wr":"ちゅうもんやけっさいのぼたんをおしたときに、かくにんのがめんをだすかどうかをきめるせっていです。おしまちがいをふせぎたいか、すばやくそうさしたいかでえらびます。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「けっさいかんれん」をひらく つかいたいこうもくにちぇっくをいれる なりゆきえんとりーでかくにん ：SELL / BUY をおしたあとにかくにんがでます。おふにすると、おしたしゅんかんにはっちゅうします わんくりっくけっさい ：おんにすると、かくにんなしですぐにけっさいします ぜんけっさいときにひょうじちゅうのつうかぺあのみけっさい ：おんにすると、ぜんけっさいでいまひょうじしているつうかぺあのぽじしょんだけをけっさいします ごちゅうい おしまちがいをふせぐため、なれるまでは「なりゆきえんとりーでかくにん」をおんのままつかうのがおすすめです。"},{"f":"ytt-web-f-trade.html","pt":"注文・ロット・決済","no":"2","id":"lot","n":"ロットの決め方","dv":"","k":"ロットの決め方 ロットの自動計算 損失率固定 2.0% 残高：lot固定モード ロットの決め方 損失率固定モード ロットの決め方 損失額固定モード ロットの決め方","w":"ロット（注文の量）を、自分で計算しなくても自動で決めてくれる機能です。決め方は「損失率固定」「損失額固定」「残高：lot固定」の3つで、はじめは「損失率固定（2.0%）」になっています。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「ロットの決め方」を開く 3つの決め方から1つ選び、右の − ＋ で値を決める（数字をタップ・クリックして打ち込むこともできます） 損失率固定のときは、残高の下の「損失率固定」の − ＋ でも変えられます。隣の「許容損失」で、1回に失ってよい金額を確かめる 損失率固定（おすすめ） ：1回の損失を、残高の○%に固定します。SLまでの幅に合わせてロットが決まり、SLが遠いほど小さく、近いほど大きくなります。例：残高100万円・2%なら、損切りになったときの損失は2万円。デイトレードやスイングなど、いろいろなトレードに使えます 損失額固定 ：1回の損失を、金額で固定します。ロットの決まり方は損失率固定と同じで、%の代わりに金額で決めます。例：¥5,000なら、損切りになったときの損失は5,000円。残高が増えても減っても、1回の損失の額は変わりません 残高：lot固定 ：残高10万円あたりのロットを固定します。SLの位置ではロットは変わりません。例：「10万円：0.10lot」なら、残高100万円で1.00lot、120万円で1.20lot。狙うpips数がだいたい決まっているスキャルピングなどに便利です 損失率固定・損失額固定はSLから損失を計算するので、コピーモードでは、SLの無いポジションはコピーされません 計算したロットは、証券会社の最小ロット・刻みに合わせて丸められます。想定損失は、丸めたあとのロットで出し直すので、実際の損失と合います ロットが証券会社の上限を超えるときは、何回かに分けてエントリーできます（分割エントリー） アップデート予定 分割エントリーのオン・オフと分ける間隔、取引手数料、ロットの計算にボーナスを含めるかが、連携ツール（EA）の設定からWeb版YTTの設定に移ります SLまでの幅に合わせて、ロットが自動で変わるところです（PC・損失率固定）。 タップで拡大","nr":"ろっとのきめかた","kr":"ろっとのきめかた ろっとのじどうけいさん そんしつりつこてい 2.0% ざんだか：lotこていもーど ろっとのきめかた そんしつりつこていもーど ろっとのきめかた そんしつひたいこていもーど ろっとのきめかた","wr":"ろっと（ちゅうもんのりょう）を、じぶんでけいさんしなくてもじどうできめてくれるきのうです。きめかたは「そんしつりつこてい」「そんしつひたいこてい」「ざんだか：lotこてい」の3つで、はじめは「そんしつりつこてい（2.0%）」になっています。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ろっとのきめかた」をひらく 3つのきめかたから1つえらび、みぎの − ＋ であたいをきめる（すうじをたっぷ・くりっくしてうちこむこともできます） そんしつりつこていのときは、ざんだかのしたの「そんしつりつこてい」の − ＋ でもかえられます。となりの「きょようそんしつ」で、1かいにうってよいきんがくをたしかめる そんしつりつこてい（おすすめ） ：1かいのそんしつを、ざんだかの○%にこていします。SLまでのはばにあわせてろっとがきまり、SLがとおいほどちーさく、ちかいほどおおきくなります。れい：ざんだか100まんえん・2%なら、そんぎりりになったときのそんしつは2まんえん。でいとれーどやすいんぐなど、いろいろなとれーどにつかえます そんしつひたいこてい ：1かいのそんしつを、きんがくでこていします。ろっとのきまりかたはそんしつりつこていとおなじで、%のかわりにきんがくできめます。れい：¥5,000なら、そんぎりりになったときのそんしつは5,000えん。ざんだかがふえてもへっても、1かいのそんしつのひたいはかわりません ざんだか：lotこてい ：ざんだか10まんえんあたりのろっとをこていします。SLのいちではろっとはかわりません。れい：「10まんえん：0.10lot」なら、ざんだか100まんえんで1.00lot、120まんえんで1.20lot。ねらうpipsかずがだいたいきまっているすきゃるぴんぐなどにべんりです そんしつりつこてい・そんしつひたいこていはSLからそんしつをけいさんするので、こぴーもーどでは、SLのないぽじしょんはこぴーされません けいさんしたろっとは、しょうけんがいしゃのさいしょうろっと・きざみにあわせてまるめられます。そうていそんしつは、まるめたあとのろっとでだしなおすので、じっさいのそんしつとあいます ろっとがしょうけんがいしゃのじょうげんをこえるときは、なんかいかにわけてえんとりーできます（ぶんかつえんとりー） あっぷでーとよてい ぶんかつえんとりーのおん・おふとわけるかんかく、とりひきてすうりょう、ろっとのけいさんにぼーなすをふくめるかが、れんけいつーる（EA）のせっていからWebはんYTTのせっていにうつります SLまでのはばにあわせて、ろっとがじどうでかわるところです（PC・そんしつりつこてい）。 たっぷでかくだい"},{"f":"ytt-web-f-trade.html","pt":"注文・ロット・決済","no":"2","id":"auto-be","n":"自動建値設置","dv":"","k":"自動処理 ポジションを持ったあと オフ 建値設置pips 自動処理 自動建値設置 自動処理","w":"ポジションを2つ以上持ったときに、損切り（SL）を自動で「建値」に動かしてくれる機能です。建値とは、決済しても損益がほぼ0になる価格のこと。買い増し・売り増しをしても、損をしにくくなります。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「自動処理」を開く 「自動建値設置」にチェックを入れる ポジションを複数持つと、SLが自動で建値に移ります 建値は最初「＋1pips」。1pipsだけ利益が出る位置で決済されます（「建値設置pips」で変えられます） ピラミッディング（利益が出ている方向に、ポジションを買い増し・売り増しすること）をするときに便利です","nr":"じどうたてねせっち","kr":"じどうしょり ぽじしょんをもったあと おふ たてねせっちpips じどうしょり じどうたてねせっち じどうしょり","wr":"ぽじしょんを2ついじょうもったときに、そんぎりり（SL）をじどうで「たてね」にうごかしてくれるきのうです。たてねとは、けっさいしてもそんえきがほぼ0になるかかくのこと。かいまし・うりましをしても、そこなをしにくくなります。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「じどうしょり」をひらく 「じどうたてねせっち」にちぇっくをいれる ぽじしょんをふくすうじつと、SLがじどうでたてねにうつります たてねはさいしょ「＋1pips」。1pipsだけりえきがでるいちでけっさいされます（「たてねせっちpips」でかえられます） ぴらみっでぃんぐ（りえきがでているほうこうに、ぽじしょんをかいまし・うりましすること）をするときにべんりです"},{"f":"ytt-web-f-trade.html","pt":"注文・ロット・決済","no":"2","id":"trail","n":"TPのトレイル化","dv":"","k":"自動処理 ポジションを持ったあと オフ トレイル追随pips 自動処理 TPのトレイル化 自動処理","w":"利確（TP）の位置に来てもすぐには決済せず、さらに伸びる利益を追いかける機能です。価格が利益の方向に進むと、損切り（SL）が一定の幅でついていき、価格が戻ってきたところで決済されます。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「自動処理」を開く 「TPのトレイル化」にチェックを入れる オンにすると、TPのラインが「トレイルが始まるライン」に変わります SLがついていく幅は、最初は10pips（「トレイル追随pips」で変えられます） 大きく伸びそうな場面で、利益をできるだけ伸ばしたいときに使います","nr":"TPのとれいるか","kr":"じどうしょり ぽじしょんをもったあと おふ とれいるついずいpips じどうしょり TPのとれいるか じどうしょり","wr":"りかく（TP）のいちにきてもすぐにはけっさいせず、さらにのびるりえきをおいかけるきのうです。かかくがりえきのほうこうにすすむと、そんぎりり（SL）がいっていのはばでついていき、かかくがもどってきたところでけっさいされます。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「じどうしょり」をひらく 「TPのとれいるか」にちぇっくをいれる おんにすると、TPのらいんが「とれいるがはじまるらいん」にかわります SLがついていくはばは、さいしょは10pips（「とれいるついずいpips」でかえられます） おおきくのびそうなばめんで、りえきをできるだけのばしたいときにつかいます"},{"f":"ytt-web-f-trade.html","pt":"注文・ロット・決済","no":"2","id":"rr-fix","n":"RR比固定","dv":"","k":"自動処理 ポジションを持ったあと オフ（1.00倍） RR比固定 自動処理","w":"RR比（リスクリワード比＝利益の幅 ÷ 損失の幅）を、決めた倍率に固定する設定です。1.00倍なら、利確までの幅と損切りまでの幅が同じになります。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「自動処理」を開く 「RR比固定」にチェックを入れ、− ＋ で倍率を決める オンにすると、シナリオで TPとSLのどちらを動かしても、もう片方が自動でついてきます （決めたRR比のまま） TPとSLを別々の幅にしたいときは、オフにします","nr":"RRひこてい","kr":"じどうしょり ぽじしょんをもったあと おふ（1.00ばい） RRひこてい じどうしょり","wr":"RRひ（りすくりわーどひひりえきのはば ÷ そんしつのはば）を、きめたばいりつにこていするせっていです。1.00ばいなら、りかくまでのはばとそんぎりりまでのはばがおなじになります。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「じどうしょり」をひらく 「RRひこてい」にちぇっくをいれ、− ＋ でばいりつをきめる おんにすると、しなりおで TPとSLのどちらをうごかしても、もうかたほうがじどうでついてきます （きめたRRひのまま） TPとSLをべつべつのはばにしたいときは、おふにします"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"build","n":"シナリオ構築","dv":"","k":"シナリオを描く シナリオ構築 パネルは非表示 シナリオ構築パネルを表示 表示","w":"エントリーする前に、「このあと相場はこう動くだろう」という値動きの道筋（シナリオ）を、チャートに描く機能です。エントリー・利確・損切りの位置も一緒に置くと、そのトレードのRR比（利益と損失の比率）が分かります。トレードの計画を目に見える形にできるので、安定したトレードの基本になります。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「シナリオ構築パネルを表示」をオンにする 右のパネルの「シナリオ構築」を押す チャートをクリックして、値動きの道筋を描く（クリックで折り返し、ダブルクリックで終点） 続けてクリックで、想定エントリー → 想定利確 → 想定損切りの位置を置く 描き終わると、RR比などが表示されます 線やアイコンは、ダブルクリックで選ぶと動かせます 「非表示」で一時的に隠し、「全削除」でまとめて消せます PCは、キーボードの Shift＋S でも、シナリオ構築のパネルを出せます 見立てを描くだけの機能で、注文とはつながっていません 。実際に注文するのは「 ロングシナリオ・ショートシナリオ 」です","nr":"しなりおこうちく","kr":"しなりおをえがく しなりおこうちく ぱねるはひひょうじ しなりおこうちくぱねるをひょうじ ひょうじ","wr":"えんとりーするまえに、「このあとそうばはこううごくだろう」というあたいうごきのみちすじ（しなりお）を、ちゃーとにえがくきのうです。えんとりー・りかく・そんぎりりのいちもいっしょにおくと、そのとれーどのRRひ（りえきとそんしつのひりつ）がわかります。とれーどのけいかくをめにみえるかたちにできるので、あんていしたとれーどのきほんになります。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「しなりおこうちくぱねるをひょうじ」をおんにする みぎのぱねるの「しなりおこうちく」をおす ちゃーとをくりっくして、あたいうごきのみちすじをえがく（くりっくでおりかえし、だぶるくりっくでしゅうてん） つづけてくりっくで、そうていえんとりー → そうていりかく → そうていそんぎりりのいちをおく えがきおわると、RRひなどがひょうじされます せんやあいこんは、だぶるくりっくでえらぶとうごかせます 「ひひょうじ」でいちじてきにかくし、「ぜんさくじょ」でまとめてけせます PCは、きーぼーどの Shift＋S でも、しなりおこうちくのぱねるをだせます みたてをえがくだけのきのうで、ちゅうもんとはつながっていません 。じっさいにちゅうもんするのは「 ろんぐしなりお・しょーとしなりお 」です"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"scenario","n":"シナリオ（TP/SL）","dv":"","k":"シナリオで注文 シナリオで注文する ","w":"エントリーと同時に、利確（TP）と損切り（SL）を置ける機能です。先にTPとSLの線を置いてから注文するので、RR比（利益と損失の比率）を確かめてからエントリーできます。","t":"「ロングシナリオ」（買い）か「ショートシナリオ」（売り）を押す チャートに出たTPとSLの線を、ドラッグして好きな位置に動かす RR比が1以上なのを確かめて、エントリーする（または予約にする） 損失率固定モードなら、SLに届いたときの損失が決めた割合になるように、ロットが自動で決まります 線を置いただけでは発注されません（「構築中」の状態） PCは、キーボードの Shift＋X で、出したシナリオを削除できます アップデート予定 「削除」のボタンが上の方に移り、エントリーのボタンと離れます（押しまちがい防止）","nr":"しなりお（TP/SL）","kr":"しなりおでちゅうもん しなりおでちゅうもんする ","wr":"えんとりーとどうじに、りかく（TP）とそんぎりり（SL）をおけるきのうです。さきにTPとSLのせんをおいてからちゅうもんするので、RRひ（りえきとそんしつのひりつ）をたしかめてからえんとりーできます。","tr":"「ろんぐしなりお」（かい）か「しょーとしなりお」（うり）をおす ちゃーとにでたTPとSLのせんを、どらっぐしてすきないちにうごかす RRひが1いじょうなのをたしかめて、えんとりーする（またはよやくにする） そんしつりつこていもーどなら、SLにとどいたときのそんしつがきめたわりあいになるように、ろっとがじどうできまります せんをおいただけでははっちゅうされません（「こうちくちゅう」のじょうたい） PCは、きーぼーどの Shift＋X で、だしたしなりおをさくじょできます あっぷでーとよてい 「さくじょ」のぼたんがうえのほうにうつり、えんとりーのぼたんとはなれます（おしまちがいぼうし）"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"reserve","n":"予約注文","dv":"","k":"シナリオで注文 シナリオで注文する ","w":"「この価格まで来たらエントリーしたい」というときに、注文を予約しておける機能です。チャートを見ていなくても、決めた価格に来たら自動でエントリーします。","t":"シナリオ（TP/SL）を組む シナリオの中の「予約（今すぐではなく、別の値で入りたいとき）」をオンにする チャートの緑の線を、エントリーしたい価格まで動かし、予約のボタンを押す 予約中の注文は、PCは右のパネルの「待機中のシナリオ」、スマホは下のメニューの「ポジション」で確認・取り消しできます チャート上では、構築中は破線、予約中は実線で表示されます 取引ツール（MT4 / MT5 / cTrader）とPCが動いている間だけ働きます（cTrader Cloud版を除く） 予約とエントリートリガーは、同時には使えません（片方をオンにすると、もう片方はオフになります）","nr":"よやくちゅうもん","kr":"しなりおでちゅうもん しなりおでちゅうもんする ","wr":"「このかかくまできたらえんとりーしたい」というときに、ちゅうもんをよやくしておけるきのうです。ちゃーとをみていなくても、きめたかかくにきたらじどうでえんとりーします。","tr":"しなりお（TP/SL）をくむ しなりおのなかの「よやく（いますぐではなく、べつのあたいでいりたいとき）」をおんにする ちゃーとのみどりのせんを、えんとりーしたいかかくまでうごかし、よやくのぼたんをおす よやくなかのちゅうもんは、PCはみぎのぱねるの「たいきちゅうのしなりお」、すまほはしたのめにゅーの「ぽじしょん」でかくにん・とりけしできます ちゃーとうえでは、こうちくちゅうははせん、よやくなかはじっせんでひょうじされます とりひきつーる（MT4 / MT5 / cTrader）とPCがうごいているかんだけはたらきます（cTrader Cloudはんをのぞく） よやくとえんとりーとりがーは、どうじにはつかえません（かたほうをおんにすると、もうかたほうはおふになります）"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"trigger","n":"エントリートリガー","dv":"","k":"エントリーの条件 条件をつけてエントリー  トレンド転換の時間足 エントリートリガー 押し目の時間足 エントリートリガー RR比 エントリートリガー","w":"予約注文に「条件」をつける機能です。ラインに触れたらすぐに入るのではなく、「トレンドが転換したら」「押し目が来たら」「RR比がよくなったら」といった条件がそろったときだけエントリーします。","t":"「ロングシナリオ」か「ショートシナリオ」を押して、TPとSLの位置を決める シナリオの中の「エントリートリガー」を開く（スマホは「トリガー」） 使う条件をオンにする（判断に使う時間足も選べる） 「エントリートリガーで SELL 待機」（買いなら BUY）を押す 待機を始めると「待機中のシナリオ」に入り、条件がそろったところで成行でエントリーします トレンド転換で注文 ：決めた時間足（最初はM5）で、トレンドが転換したらエントリー 押し目で注文 ：押し目（いったん戻ったところ）のタイミングでエントリー RR比成立で注文 ：RR比が決めた数値（最初は1.00）以上になったらエントリー 「トレンド転換」と「押し目」は、どちらか1つだけ使えます。「RR比成立」は、どちらとも組み合わせられます エントリートリガーをオンにすると、予約はオフになります 「トレンド転換＋RR比」「押し目＋RR比」のように、2つを組み合わせることもできます。時間足やRR比の最初の値は、右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「エントリートリガー」 で変えられます。","nr":"えんとりーとりがー","kr":"えんとりーのじょうけん じょうけんをつけてえんとりー  とれんどてんかんのじかんあし えんとりーとりがー おしめのじかんあし えんとりーとりがー RRひ えんとりーとりがー","wr":"よやくちゅうもんに「じょうけん」をつけるきのうです。らいんにふれたらすぐにいるのではなく、「とれんどがてんかんしたら」「おしめがきたら」「RRひがよくなったら」といったじょうけんがそろったときだけえんとりーします。","tr":"「ろんぐしなりお」か「しょーとしなりお」をおして、TPとSLのいちをきめる しなりおのなかの「えんとりーとりがー」をひらく（すまほは「とりがー」） つかうじょうけんをおんにする（はんだんにつかうじかんあしもえらべる） 「えんとりーとりがーで SELL たいき」（かいなら BUY）をおす たいきをはじめると「たいきちゅうのしなりお」にいり、じょうけんがそろったところでなりゆきでえんとりーします とれんどてんかんでちゅうもん ：きめたじかんあし（さいしょはM5）で、とれんどがてんかんしたらえんとりー おしめでちゅうもん ：おしめ（いったんもどったところ）のたいみんぐでえんとりー RRひせいりつでちゅうもん ：RRひがきめたすうち（さいしょは1.00）いじょうになったらえんとりー 「とれんどてんかん」と「おしめ」は、どちらか1つだけつかえます。「RRひせいりつ」は、どちらともくみあわせられます えんとりーとりがーをおんにすると、よやくはおふになります 「とれんどてんかん＋RRひ」「おしめ＋RRひ」のように、2つをくみあわせることもできます。じかんあしやRRひのさいしょのあたいは、みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「えんとりーとりがー」 でかえられます。"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"conditions","n":"条件付け","dv":"","k":"条件付け エントリーの前後の決まりごと ","w":"シナリオに、エントリーの前やエントリーしたあとの「決まりごと」を追加する機能です。追加した決まりごとはチャートに線で表示され、価格がその線まで来ると、決めておいた動き（ポジションの追加、建値への移動など）を自動で行います。","t":"「ロングシナリオ」か「ショートシナリオ」を押して、TPとSLの位置を決める シナリオの中の「条件付け」を開く 使いたい項目の ＋ を押す チャートに出た線を動かして、位置を決める 押し目 ：いったん押し目の線まで来てから、予約の価格でエントリーする（予約のときだけ） 崩壊 ：予約中に、この価格まで来たらシナリオを取りやめる 建値 ：この価格まで来たら、SLを建値に動かす トレイル ：この価格まで来たら、SLが利益の方向についていく 1/2決済 ：この価格まで来たら、半分だけ決済する 追加ポジ ：この価格まで来たら、ポジションを追加する","nr":"じょうけんづけ","kr":"じょうけんづけ えんとりーのぜんごのきまりごと ","wr":"しなりおに、えんとりーのまえやえんとりーしたあとの「きまりごと」をついかするきのうです。ついかしたきまりごとはちゃーとにせんでひょうじされ、かかくがそのせんまでくると、きめておいたうごき（ぽじしょんのついか、たてねへのいどうなど）をじどうでおこないます。","tr":"「ろんぐしなりお」か「しょーとしなりお」をおして、TPとSLのいちをきめる しなりおのなかの「じょうけんづけ」をひらく つかいたいこうもくの ＋ をおす ちゃーとにでたせんをうごかして、いちをきめる おしめ ：いったんおしめのせんまできてから、よやくのかかくでえんとりーする（よやくのときだけ） ほうかい ：よやくなかに、このかかくまできたらしなりおをとりやめる たてね ：このかかくまできたら、SLをたてねにうごかす とれいる ：このかかくまできたら、SLがりえきのほうこうについていく 1/2けっさい ：このかかくまできたら、はんぶんだけけっさいする ついかぽじ ：このかかくまできたら、ぽじしょんをついかする"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"addpos","n":"追加ポジ","dv":"","k":"条件付け エントリーの前後の決まりごと ロット倍率 0.50 ロット倍率 追加ポジ 追加ポジは全体の損失で計算 追加ポジ","w":"エントリーしたあと、決めた価格まで来たら、ポジションを買い増し（売り増し）する機能です。追加するロットは、最初のポジションに対する倍率で決めます。","t":"シナリオを組み、「条件付け」を開く 「追加ポジ」の ＋ を押す チャートに出た「追加ポジ」の線を、追加したい価格まで動かす エントリーする（予約でも使えます） 1本ごとに「×0.50」のように、最初のロットに対する倍率がつきます（0.50なら半分）。倍率は、チャートに出た「追加ポジ」の線の左の数字で1本ずつ変えられます（最初の値は設定で変えられます） ＋ を押すたびに線が増えます。いらない線は × で消せます エントリーすると線は「追加ポジ#番号」になり、価格が来たら自動で追加されます 追加ポジの線は、5本まで置けます 倍率の最初の値は、右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「追加ポジ」 で変えられます。 「追加ポジは全体の損失で計算」をオンにすると、ロットを通貨ペアごとではなく、全体の損失の合計をもとに計算します（最初はオフ）。","nr":"ついかぽじ","kr":"じょうけんづけ えんとりーのぜんごのきまりごと ろっとばいりつ 0.50 ろっとばいりつ ついかぽじ ついかぽじはぜんたいのそんしつでけいさん ついかぽじ","wr":"えんとりーしたあと、きめたかかくまできたら、ぽじしょんをかいまし（うりまし）するきのうです。ついかするろっとは、さいしょのぽじしょんにたいするばいりつできめます。","tr":"しなりおをくみ、「じょうけんづけ」をひらく 「ついかぽじ」の ＋ をおす ちゃーとにでた「ついかぽじ」のせんを、ついかしたいかかくまでうごかす えんとりーする（よやくでもつかえます） 1ほんごとに「×0.50」のように、さいしょのろっとにたいするばいりつがつきます（0.50ならはんぶん）。ばいりつは、ちゃーとにでた「ついかぽじ」のせんのひだりのすうじで1ほんずつかえられます（さいしょのあたいはせっていでかえられます） ＋ をおすたびにせんがふえます。いらないせんは × でけせます えんとりーするとせんは「ついかぽじ#ばんごう」になり、かかくがきたらじどうでついかされます ついかぽじのせんは、5ほんまでおけます ばいりつのさいしょのあたいは、みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ついかぽじ」 でかえられます。 「ついかぽじはぜんたいのそんしつでけいさん」をおんにすると、ろっとをつうかぺあごとではなく、ぜんたいのそんしつのごうけいをもとにけいさんします（さいしょはおふ）。"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"pullback","n":"押し目","dv":"","k":"条件付け エントリーの前後の決まりごと ","w":"旧YTTの「成立条件ライン（成立要件）」にあたる、水色の線です。「いったんこの価格まで来てから」という条件をつけられます。価格が押し目の線に来たあと、予約の線（緑の線）まで戻ってきたところでエントリーします。押し目（上がっている途中の一時的な下げ）や戻り（下がっている途中の一時的な上げ）を待ってから入りたいときに使います。","t":"「ロングシナリオ」か「ショートシナリオ」を押して、TPとSLの位置を決める 「予約」をオンにする（または「エントリートリガー」を設定する） 「条件付け」を開き、「押し目」の ＋ を押す チャートに出た「押し目1」の線を動かして、「ここで SELL を予約」（買いなら BUY）を押す 押し目は、 「予約」か「エントリートリガー」を設定すると 置けるようになります（どちらも設定していないと「未設定」のままで ＋ が出ません） 予約すると「待機中のシナリオ」に入り、「押し目 0/1」のように表示されます 押し目の ＋ を押すたびに線が1本ずつ増え、3本（押し目1・押し目2・押し目3）まで置けます 旧YTTの 「成立条件ライン（成立要件）」は、この押し目（水色の線） です 押し目を置くと、 押し目1から順番にすべての線に届いてから エントリーします 見張りはサーバーで行うので、Web版YTTの画面を閉じていても続きます","nr":"おしめ","kr":"じょうけんづけ えんとりーのぜんごのきまりごと ","wr":"きゅうYTTの「せいりつじょうけんらいん（せいりつようけん）」にあたる、みずいろのせんです。「いったんこのかかくまできてから」というじょうけんをつけられます。かかくがおしめのせんにきたあと、よやくのせん（みどりのせん）までもどってきたところでえんとりーします。おしめ（あがっているとちゅうのいちじてきなさげ）やもどり（さがっているとちゅうのいちじてきなあげ）をまってからいりたいときにつかいます。","tr":"「ろんぐしなりお」か「しょーとしなりお」をおして、TPとSLのいちをきめる 「よやく」をおんにする（または「えんとりーとりがー」をせっていする） 「じょうけんづけ」をひらき、「おしめ」の ＋ をおす ちゃーとにでた「おしめ1」のせんをうごかして、「ここで SELL をよやく」（かいなら BUY）をおす おしめは、 「よやく」か「えんとりーとりがー」をせっていすると おけるようになります（どちらもせっていしていないと「みせってい」のままで ＋ がでません） よやくすると「たいきちゅうのしなりお」にいり、「おしめ 0/1」のようにひょうじされます おしめの ＋ をおすたびにせんが1ほんずつふえ、3ほん（おしめ1・おしめ2・おしめ3）までおけます きゅうYTTの 「せいりつじょうけんらいん（せいりつようけん）」は、このおしめ（みずいろのせん） です おしめをおくと、 おしめ1からじゅんばんにすべてのせんにとどいてから えんとりーします みはりはさーばーでおこなうので、WebはんYTTのがめんをとじていてもつづきます"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"collapse","n":"崩壊","dv":"","k":"条件付け エントリーの前後の決まりごと ","w":"予約中のシナリオに、「この価格まで来たら、シナリオを取りやめる」という線を置く機能です。相場が思っていたのと違う方向に動いたとき、エントリーする前に自動で予約を取り消せます。","t":"「ショートシナリオ」か「ロングシナリオ」を押して、TPとSLの位置を決める（スマホは右上の「シナリオ」から） 「予約」をオンにして、緑の線をエントリーしたい価格まで動かす 「条件付け」を開き、「崩壊」の ＋ を押す チャートに出た崩壊の線を、やめたい価格まで動かす ＋ を1回押すと、 上と下に1本ずつ 出ます（「条件付け」は「崩壊2」と表示されます） 線はいらなければ、チップの × か、チャートの線の × で消せます 「成行注文では設置不可」と出るとおり、予約（今すぐではなく、別の値で入る）のときに使います 旧YTTの「シナリオ崩壊」と同じ考え方です 価格が崩壊の線に来ると、まだエントリーしていない予約が取り消されます アップデート予定 取り消されたときに通知が届くようになります","nr":"ほうかい","kr":"じょうけんづけ えんとりーのぜんごのきまりごと ","wr":"よやくなかのしなりおに、「このかかくまできたら、しなりおをとりやめる」というせんをおくきのうです。そうばがおもっていたのとちがうほうこうにうごいたとき、えんとりーするまえにじどうでよやくをとりけせます。","tr":"「しょーとしなりお」か「ろんぐしなりお」をおして、TPとSLのいちをきめる（すまほはみぎうえの「しなりお」から） 「よやく」をおんにして、みどりのせんをえんとりーしたいかかくまでうごかす 「じょうけんづけ」をひらき、「ほうかい」の ＋ をおす ちゃーとにでたほうかいのせんを、やめたいかかくまでうごかす ＋ を1かいおすと、 あがとしたに1ほんずつ でます（「じょうけんづけ」は「ほうかい2」とひょうじされます） せんはいらなければ、ちっぷの × か、ちゃーとのせんの × でけせます 「なりゆきちゅうもんではせっちふか」とでるとおり、よやく（いますぐではなく、べつのあたいでいる）のときにつかいます きゅうYTTの「しなりおほうかい」とおなじかんがえかたです かかくがほうかいのせんにくると、まだえんとりーしていないよやくがとりけされます あっぷでーとよてい とりけされたときにつうちがとどくようになります"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"be-line","n":"建値","dv":"","k":"条件付け エントリーの前後の決まりごと ","w":"エントリーしたあと、価格がこの線まで来たら、損切り（SL）を自動で建値（損益がほぼ0になる価格）に動かす機能です。ある程度利益が出たところで、負けないトレードにしておけます。","t":"「条件付け」の「建値」の ＋ を押す チャートに出た線を、建値にしたい価格まで動かす 「ここで SELL」（買いなら BUY）を押してエントリーする。線はそのまま残ります ＋ を1回押すと、 上と下に1本ずつ 出ます（どちらから来ても建値にできます） 「自動建値設置」（ポジションが2つ以上になったら建値へ）とは別に、「この価格まで来たら」を自分で決められます 建値からどれだけ利益側にSLを置くかは、設定の「建値設置pips」（最初は1.0pips） 価格が線に来ると、SLが建値（＋「建値設置pips」ぶん利益側）に移ります。 移ったときは、通知が届きます （届き先は口座の種類で決まります。 スマホに通知を届ける設定 ） PCは、保有中のポジションを選んだ状態でキーボードの Q を押しても、建値の線を置けます","nr":"たてね","kr":"じょうけんづけ えんとりーのぜんごのきまりごと ","wr":"えんとりーしたあと、かかくがこのせんまできたら、そんぎりり（SL）をじどうでたてね（そんえきがほぼ0になるかかく）にうごかすきのうです。あるていどりえきがでたところで、まけないとれーどにしておけます。","tr":"「じょうけんづけ」の「たてね」の ＋ をおす ちゃーとにでたせんを、たてねにしたいかかくまでうごかす 「ここで SELL」（かいなら BUY）をおしてえんとりーする。せんはそのままのこります ＋ を1かいおすと、 あがとしたに1ほんずつ でます（どちらからきてもたてねにできます） 「じどうたてねせっち」（ぽじしょんが2ついじょうになったらたてねへ）とはべつに、「このかかくまできたら」をじぶんできめられます たてねからどれだけりえきがわにSLをおくかは、せっていの「たてねせっちpips」（さいしょは1.0pips） かかくがせんにくると、SLがたてね（＋「たてねせっちpips」ぶんりえきがわ）にうつります。 うつったときは、つうちがとどきます （とどきさきはこうざのしゅるいできまります。 すまほにつうちをとどけるせってい ） PCは、ほゆうなかのぽじしょんをえらんだじょうたいできーぼーどの Q をおしても、たてねのせんをおけます"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"trail-line","n":"トレイル","dv":"","k":"条件付け エントリーの前後の決まりごと ","w":"エントリーしたあと、価格がこの線まで来たら、トレイル（利益の方向に、損切りが一定の幅でついていく動き）を始める機能です。利益をできるだけ伸ばしたいときに使います。","t":"「条件付け」の「トレイル」の ＋ を押す チャートに出た線を、トレイルを始めたい価格まで動かす 「ここで SELL」（買いなら BUY）を押してエントリーする。線はそのまま残ります 線は1本です（建値や崩壊のように上下2本にはなりません） ついていく幅は、設定の「トレイル追随pips」（最初は10pips） TPの位置から始めたいときは、設定の「TPのトレイル化」も使えます 価格が線に来ると、そこから「トレイル追随pips」の幅で、SLが価格についていきます。 トレイルが始まったときは、通知が届きます （届き先は口座の種類で決まります。 スマホに通知を届ける設定 ） PCは、保有中のポジションを選んだ状態でキーボードの W を押しても、トレイルの線を置けます","nr":"とれいる","kr":"じょうけんづけ えんとりーのぜんごのきまりごと ","wr":"えんとりーしたあと、かかくがこのせんまできたら、とれいる（りえきのほうこうに、そんぎりりがいっていのはばでついていくうごき）をはじめるきのうです。りえきをできるだけのばしたいときにつかいます。","tr":"「じょうけんづけ」の「とれいる」の ＋ をおす ちゃーとにでたせんを、とれいるをはじめたいかかくまでうごかす 「ここで SELL」（かいなら BUY）をおしてえんとりーする。せんはそのままのこります せんは1ほんです（たてねやほうかいのようにじょうげ2ほんにはなりません） ついていくはばは、せっていの「とれいるついずいpips」（さいしょは10pips） TPのいちからはじめたいときは、せっていの「TPのとれいるか」もつかえます かかくがせんにくると、そこから「とれいるついずいpips」のはばで、SLがかかくについていきます。 とれいるがはじまったときは、つうちがとどきます （とどきさきはこうざのしゅるいできまります。 すまほにつうちをとどけるせってい ） PCは、ほゆうなかのぽじしょんをえらんだじょうたいできーぼーどの W をおしても、とれいるのせんをおけます"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"half-line","n":"1/2決済","dv":"","k":"条件付け エントリーの前後の決まりごと ","w":"エントリーしたあと、価格がこの線まで来たら、ポジションの半分を自動で決済する機能です。利益の一部を先に確定させて、残りで利益を伸ばせます。","t":"「条件付け」の「1/2決済」の ＋ を押す チャートに出た線を、半分決済したい価格まで動かす 「ここで SELL」（買いなら BUY）を押してエントリーする。線はそのまま残ります 線は1本です 価格が線に来ると、ポジションのロットの半分が決済されます。 決済されたときは、通知が届きます （届き先は口座の種類で決まります。 スマホに通知を届ける設定 ）","nr":"1/2けっさい","kr":"じょうけんづけ えんとりーのぜんごのきまりごと ","wr":"えんとりーしたあと、かかくがこのせんまできたら、ぽじしょんのはんぶんをじどうでけっさいするきのうです。りえきのいちぶをさきにかくていさせて、のこりでりえきをのばせます。","tr":"「じょうけんづけ」の「1/2けっさい」の ＋ をおす ちゃーとにでたせんを、はんぶんけっさいしたいかかくまでうごかす 「ここで SELL」（かいなら BUY）をおしてえんとりーする。せんはそのままのこります せんは1ほんです かかくがせんにくると、ぽじしょんのろっとのはんぶんがけっさいされます。 けっさいされたときは、つうちがとどきます （とどきさきはこうざのしゅるいできまります。 すまほにつうちをとどけるせってい ）"},{"f":"ytt-web-f-scenario.html","pt":"シナリオ・予約注文","no":"3","id":"order-ops","n":"注文操作","dv":"","k":"エントリーしたあと 持っているポジションの操作 ","w":"エントリーしたあとのポジションに、あとから決済のしかたを追加できる機能です。条件付けを入れずにエントリーしたときも、ここから追加できます。","t":"エントリーして、ポジションを持つ 「注文操作」を開く（PCは右のパネル、スマホはチャートの下） 「トレイルライン」「建値設置」「1/2決済」から、使いたいものをオンにする チャートに出た線を、置きたい価格まで動かす ポジションを持っているときに使う機能です（動画は、エントリーするところから始まります） オンにすると「設置済み」と出て、チャートに線が出ます（条件付けと同じ線です）。価格が線に来て、SLが動いたり半分決済されたりすると、通知が届きます チャートに「〇〇 注文操作ライン」の小さな画面が出るので、そこで価格を打ち直して「変更を確定」もできます 決済ラインを一括で動かす ：TPとSLをまとめて移動できます","nr":"ちゅうもんそうさ","kr":"えんとりーしたあと もっているぽじしょんのそうさ ","wr":"えんとりーしたあとのぽじしょんに、あとからけっさいのしかたをついかできるきのうです。じょうけんづけをいれずにえんとりーしたときも、ここからついかできます。","tr":"えんとりーして、ぽじしょんをもつ 「ちゅうもんそうさ」をひらく（PCはみぎのぱねる、すまほはちゃーとのした） 「とれいるらいん」「たてねせっち」「1/2けっさい」から、つかいたいものをおんにする ちゃーとにでたせんを、おきたいかかくまでうごかす ぽじしょんをもっているときにつかうきのうです（どうがは、えんとりーするところからはじまります） おんにすると「せっちすみ」とでて、ちゃーとにせんがでます（じょうけんづけとおなじせんです）。かかくがせんにきて、SLがうごいたりはんぶんけっさいされたりすると、つうちがとどきます ちゃーとに「〇〇 ちゅうもんそうさらいん」のちいさながめんがでるので、そこでかかくをうちなおして「へんこうをかくてい」もできます けっさいらいんをいっかつでうごかす ：TPとSLをまとめていどうできます"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"autoline","n":"オートライン","dv":"","k":"ライン チャートに引くライン オン 水平線 オートライン 斜線 オートライン 時間足ごとのライン（色・線の種類） オートライン 重要ライン1・2、カーソルカラー（スマホ） オートライン","w":"大事な水平線・トレンドライン・チャネルラインを、自動でチャートに引いてくれる機能です。ラインは売りと買いの勢いがぶつかりやすい場所なので、自分で引かなくても、注目すべき価格が分かります。","t":"最初からオンになっています いくつかの時間足のラインが、まとめて引かれます（マルチタイムフレーム） 右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「オートライン」 で、「水平線」「斜線」のチェックを外すとそれぞれ消せます ラインの色は時間足ごとに分かれています（M1ライン・M5ライン・M15ライン…） 右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「オートライン」 で、時間足ごとに色・太さ・点線などを好きなものに変えられます","nr":"おーとらいん","kr":"らいん ちゃーとにひくらいん おん すいへいせん おーとらいん しゃせん おーとらいん じかんあしごとのらいん（いろ・せんのしゅるい） おーとらいん じゅうようらいん1・2、かーそるからー（すまほ） おーとらいん","wr":"だいじなすいへいせん・とれんどらいん・ちゃねるらいんを、じどうでちゃーとにひいてくれるきのうです。らいんはうりとかいのいきおいがぶつかりやすいばしょなので、じぶんでひかなくても、ちゅうもくすべきかかくがわかります。","tr":"さいしょからおんになっています いくつかのじかんあしのらいんが、まとめてひかれます（まるちたいむふれーむ） みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「おーとらいん」 で、「すいへいせん」「しゃせん」のちぇっくをはずすとそれぞれけせます らいんのいろはじかんあしごとにわかれています（M1らいん・M5らいん・M15らいん…） みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「おーとらいん」 で、じかんあしごとにいろ・ふとさ・てんせんなどをすきなものにかえられます"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"zigzag","n":"zigzag MTF","dv":"","k":"ライン チャートに引くライン オフ zigzag MTF表示 ZIGZAG MTF zigzag MTF表示（下位足） ZIGZAG MTF トレンド背景 ZIGZAG MTF","w":"トレンドの向き（上昇か下降か）を、ジグザグの線と背景の色で、ひと目で分かるようにする機能です。とくに初心者の方が、トレンドをつかむのに向いています。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「ZIGZAG MTF」を開く 「zigzag MTF表示」「zigzag MTF表示(下位足)」「トレンド背景」から、使うものにチェックを入れる 白い線 ：いまの時間足のジグザグ 黄色の線 ：1つ下の時間足のジグザグ 背景の色 ：緑は上昇、赤は下降。濃い緑・濃い赤は、弱いトレンド 例えば、下降トレンドに転換したあと、下位足のジグザグで戻りのタイミングを見てショート（売り）で入る、という使い方ができます。","nr":"zigzag MTF","kr":"らいん ちゃーとにひくらいん おふ zigzag MTFひょうじ ZIGZAG MTF zigzag MTFひょうじ（かいあし） ZIGZAG MTF とれんどはいけい ZIGZAG MTF","wr":"とれんどのむき（じょうしょうかかこうか）を、じぐざぐのせんとはいけいのいろで、ひとめでわかるようにするきのうです。とくにしょしんしゃのほうが、とれんどをつかむのにむいています。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ZIGZAG MTF」をひらく 「zigzag MTFひょうじ」「zigzag MTFひょうじ(かいあし)」「とれんどはいけい」から、つかうものにちぇっくをいれる しろいせん ：いまのじかんあしのじぐざぐ きいろのせん ：1つしたのじかんあしのじぐざぐ はいけいのいろ ：みどりはじょうしょう、あかはかこう。こいみどり・こいあかは、よわいとれんど たとえば、かこうとれんどにてんかんしたあと、かいあしのじぐざぐでもどりのたいみんぐをみてしょーと（うり）でいる、というつかいかたができます。"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"alertline","n":"通知ライン","dv":"","k":"ライン チャートに引くライン ","w":"チャートに置いた線に価格が来たら、お知らせしてくれる機能です。チャートをずっと見ていなくても、大事な価格に来たことに気づけます。","t":"上のメニューのベルのボタンを押す（スマホは下の「アラート」） 「通知ラインを設置」を押す チャートに出た線を、知らせてほしい価格まで動かす 「通知ラインを設置」を押す 置いた通知ラインは、ベルの中に「EURUSD 1.17096」のように一覧で出ます（1つの口座につき10本まで。口座を切り替えれば、その口座でも10本置けます）。× で消せます 上からでも下からでも、価格が線まで来ると通知します。通知した線は自動で消えるので、また使うときは置き直します 価格が線まで来ると、ベルの中の履歴に「到達で通知」と出ます 通知の届き先 は選べず、口座の種類で決まります。 MT4/MT5の口座 は、連携ツールを動かしているパソコンのMT4/MT5から、スマホのMT4/MT5アプリに届きます（はじめに設定が必要。くわしくは「もっとくわしく」）。 cTraderの口座 は、DiscordのBotからDMで届きます MT4/MT5の口座は、パソコンのMT4/MT5が止まっているあいだの通知は届きません アップデート予定 通知のたびに、パソコンのMT4/MT5でも音つきのアラートが鳴るようになります（最初はオン。設定で切り替えられます） パソコンのブラウザには、通知は出ません 高値や安値のブレイクに置いておくと、シナリオどおりに動いたときに気づけます アップデート予定 斜め（ななめ）の線（トレンドラインのような通知ライン）も置けるようになります MT4/MT5の口座の通知は、連携EAを動かしているパソコンのMT4/MT5から、スマホのMT4/MT5アプリにプッシュ通知で届きます。はじめに一度だけ、次の設定をします（画像はMT5の画面です。MT4も同じ流れです）。 cTraderの口座の方 この設定はいりません 通知は、DiscordのBotからDMで届きます。 スマホに、MT4かMT5のアプリを入れる （パソコンで使っているのと同じほうを入れます。入れてある方は次へ） MetaTrader 4 iPhone（App Store） Android（Google Play） MetaTrader 5 iPhone（App Store） Android（Google Play） スマホのMT4/MT5アプリ で、右下の「設定」をタップし、「チャットとメッセージ」を開く 画面のいちばん下に出る MetaQuotes ID （英数字）をメモする パソコンのMT5 で、上のメニューの「ツール」→「オプション」を開く 「通知」タブで「プッシュ通知機能を有効にする」にチェックを入れ、 MetaQuotes ID の欄に、2でメモしたIDを入れる 「テスト」を押して、スマホに通知が届いたら、「OK」で閉じて完了（テストでは、MetaTrader 5 から「Test message from …」と届きます）","nr":"つうちらいん","kr":"らいん ちゃーとにひくらいん ","wr":"ちゃーとにおいたせんにかかくがきたら、おしらせしてくれるきのうです。ちゃーとをずっとみていなくても、だいじなかかくにきたことにきづけます。","tr":"うえのめにゅーのべるのぼたんをおす（すまほはしたの「あらーと」） 「つうちらいんをせっち」をおす ちゃーとにでたせんを、しらせてほしいかかくまでうごかす 「つうちらいんをせっち」をおす おいたつうちらいんは、べるのなかに「EURUSD 1.17096」のようにいちらんででます（1つのこうざにつき10ほんまで。こうざをきりかえれば、そのこうざでも10ほんおけます）。× でけせます うえからでもしたからでも、かかくがせんまでくるとつうちします。つうちしたせんはじどうできえるので、またつかうときはおきなおします かかくがせんまでくると、べるのなかのりれきに「とうたつでつうち」とでます つうちのとどきさき はえらべず、こうざのしゅるいできまります。 MT4/MT5のこうざ は、れんけいつーるをうごかしているぱそこんのMT4/MT5から、すまほのMT4/MT5あぷりにとどきます（はじめにせっていがひつよう。くわしくは「もっとくわしく」）。 cTraderのこうざ は、DiscordのBotからDMでとどきます MT4/MT5のこうざは、ぱそこんのMT4/MT5がとまっているあいだのつうちはとどきません あっぷでーとよてい つうちのたびに、ぱそこんのMT4/MT5でもおとつきのあらーとがなるようになります（さいしょはおん。せっていできりかえられます） ぱそこんのぶらうざには、つうちはでません たかねややすねのぶれいくにおいておくと、しなりおどおりにうごいたときにきづけます あっぷでーとよてい ななめ（ななめ）のせん（とれんどらいんのようなつうちらいん）もおけるようになります MT4/MT5のこうざのつうちは、れんけいEAをうごかしているぱそこんのMT4/MT5から、すまほのMT4/MT5あぷりにぷっしゅつうちでとどきます。はじめにいちどだけ、つぎのせっていをします（がぞうはMT5のがめんです。MT4もおなじながれです）。 cTraderのこうざのほう このせっていはいりません つうちは、DiscordのBotからDMでとどきます。 すまほに、MT4かMT5のあぷりをいれる （ぱそこんでつかっているのとおなじほうをいれます。いれてあるかたはつぎへ） MetaTrader 4 iPhone（App Store） Android（Google Play） MetaTrader 5 iPhone（App Store） Android（Google Play） すまほのMT4/MT5あぷり で、みぎしたの「せってい」をたっぷし、「ちゃっととめっせーじ」をひらく がめんのいちばんしたにでる MetaQuotes ID （えいすうじ）をめもする ぱそこんのMT5 で、うえのめにゅーの「つーる」→「おぷしょん」をひらく 「つうち」たぶで「ぷっしゅつうちきのうをゆうこうにする」にちぇっくをいれ、 MetaQuotes ID のらんに、2でめもしたIDをいれる 「てすと」をおして、すまほにつうちがとどいたら、「OK」でとじてかんりょう（てすとでは、MetaTrader 5 から「Test message from …」ととどきます）"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"breakeven","n":"Breakeven表示","dv":"","k":"ライン チャートに引くライン オン Breakeven表示 表示","w":"損益がちょうど0になる価格（損益分岐点）に、ラインを引いてくれる機能です。","t":"ポジションごとの「Entry」の線とは別に、赤い「BreakEven」の線が出ます ポジションを複数持っていても、どこまで戻れば損益が0になるかがすぐ分かります 最初からオン。右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」 で切り替えられます","nr":"Breakevenひょうじ","kr":"らいん ちゃーとにひくらいん おん Breakevenひょうじ ひょうじ","wr":"そんえきがちょうど0になるかかく（そんえきぶんきてん）に、らいんをひいてくれるきのうです。","tr":"ぽじしょんごとの「Entry」のせんとはべつに、あかい「BreakEven」のせんがでます ぽじしょんをふくすうじっていても、どこまでもどればそんえきが0になるかがすぐわかります さいしょからおん。みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」 できりかえられます"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"entry-viz","n":"エントリーの可視化","dv":"","k":"ライン チャートに引くライン オン エントリーの可視化 表示","w":"シナリオを置いたときに、エントリーの内容をチャートの上でひと目で分かるようにする機能です。SLまでのエリアが赤、TPまでのエリアが緑の背景になり、値動きの道すじ（白い線）とRR比も出ます。","t":"赤い背景 ：エントリーからSLまでのエリア（負けたときの幅） 緑の背景 ：エントリーからTPまでのエリア（勝ったときの幅） 白い線 ：いまの価格からエントリー、TPまでの値動きの道すじ オフにすると、背景の色・白い線・RR比の表示が消え、SL・エントリー・TPの線だけになります PCでも、スマホと同じ見た目です 最初からオン。右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」 で切り替えられます","nr":"えんとりーのかしか","kr":"らいん ちゃーとにひくらいん おん えんとりーのかしか ひょうじ","wr":"しなりおをおいたときに、えんとりーのないようをちゃーとのうえでひとめでわかるようにするきのうです。SLまでのえりあがあか、TPまでのえりあがみどりのはいけいになり、あたいうごきのみちすじ（しろいせん）とRRひもでます。","tr":"あかいはいけい ：えんとりーからSLまでのえりあ（まけたときのはば） みどりのはいけい ：えんとりーからTPまでのえりあ（かったときのはば） しろいせん ：いまのかかくからえんとりー、TPまでのあたいうごきのみちすじ おふにすると、はいけいのいろ・しろいせん・RRひのひょうじがきえ、SL・えんとりー・TPのせんだけになります PCでも、すまほとおなじみためです さいしょからおん。みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」 できりかえられます"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"history","n":"チャートに取引履歴を表示","dv":"","k":"ライン チャートに引くライン オフ チャートに取引履歴を表示 表示","w":"これまでのトレードのエントリーと決済を、チャートの上に表示する機能です。どこで入って、どこで決済したかを振り返れます。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」 でオンにします 決済したトレードの、エントリーと決済の位置に▲▼の印がつき、破線で結ばれます（MT5の同じ機能と同じ見え方です） 数字での振り返りは、 損益カレンダー が便利です","nr":"ちゃーとにとりひきりれきをひょうじ","kr":"らいん ちゃーとにひくらいん おふ ちゃーとにとりひきりれきをひょうじ ひょうじ","wr":"これまでのとれーどのえんとりーとけっさいを、ちゃーとのうえにひょうじするきのうです。どこでいっって、どこでけっさいしたかをふりかえれます。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」 でおんにします けっさいしたとれーどの、えんとりーとけっさいのいちに▲▼のいんがつき、はせんでむすばれます（MT5のおなじきのうとおなじみえかたです） すうじでのふりかえりは、 そんえきかれんだー がべんりです"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"indicator","n":"経済指標表示","dv":"","k":"時間とイベント 経済指標と市場の時間 オフ 経済指標表示（アラート） 表示 経済指標：表示重要度 経済指標・セッション表示 経済指標：アラート重要度 経済指標・セッション表示 経済指標：通知タイミング 経済指標・セッション表示","w":"経済指標（雇用統計など、相場が大きく動きやすい発表）の時間に、チャートへ縦の線を引いて、指標の名前を表示する機能です。発表の前には、お知らせも届きます。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」を開く 「経済指標表示」にチェックを入れる（発表の前にお知らせがほしいときは「アラート」にも） チャートの縦の線を押す（スマホはタップ）と、くわしい内容が出る くわしい内容には、発表の日時・指標の名前・重要度（★の数）・変動幅・予想・結果が出ます 同じ時間に発表される指標も、いっしょに並びます。スマホは、そのあとに発表される指標も下に続きます ほかの線を押すと、その指標の内容に切り替わります。× で閉じます PCは、右のパネルのいちばん下に、次の重要な指標（重要度5）までの残り時間が出ます 表示するのは、今日と明日（日本時間）の指標です 最初は、重要度3以上の指標を表示し、4以上を発表の5分前にお知らせします。お知らせは、お気に入り（★）の通貨ペアに関係する指標だけです 発表の前後は相場が荒れやすいので、エントリーを避ける目安にしましょう 表示する重要度やお知らせのタイミングは、右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「経済指標・セッション表示」 で変えられます。 PCの設定画面（スマホでも同じ見え方です） タップで拡大","nr":"けいざいしひょうひょうじ","kr":"じかんといべんと けいざいしひょうとしじょうのじかん おふ けいざいしひょうひょうじ（あらーと） ひょうじ けいざいしひょう：ひょうじじゅうようど けいざいしひょう・せっしょんひょうじ けいざいしひょう：あらーとじゅうようど けいざいしひょう・せっしょんひょうじ けいざいしひょう：つうちたいみんぐ けいざいしひょう・せっしょんひょうじ","wr":"けいざいしひょう（こようとうけいなど、そうばがおおきくうごきやすいはっぴょう）のじかんに、ちゃーとへたてのせんをひいて、しひょうのなまえをひょうじするきのうです。はっぴょうのまえには、おしらせもとどきます。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」をひらく 「けいざいしひょうひょうじ」にちぇっくをいれる（はっぴょうのまえにおしらせがほしいときは「あらーと」にも） ちゃーとのたてのせんをおす（すまほはたっぷ）と、くわしいないようがでる くわしいないようには、はっぴょうのにちじ・しひょうのなまえ・じゅうようど（★のかず）・へんどうはば・よそう・けっかがでます おなじじかんにはっぴょうされるしひょうも、いっしょにならびます。すまほは、そのあとにはっぴょうされるしひょうもしたにつづきます ほかのせんをおすと、そのしひょうのないようにきりかわります。× でとじます PCは、みぎのぱねるのいちばんしたに、つぎのじゅうようなしひょう（じゅうようど5）までののこりじかんがでます ひょうじするのは、きょうとあした（にほんじかん）のしひょうです さいしょは、じゅうようど3いじょうのしひょうをひょうじし、4いじょうをはっぴょうの5ふんまえにおしらせします。おしらせは、おきにいり（★）のつうかぺあにかんけいするしひょうだけです はっぴょうのぜんごはそうばがあれやすいので、えんとりーをさけるめやすにしましょう ひょうじするじゅうようどやおしらせのたいみんぐは、みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「けいざいしひょう・せっしょんひょうじ」 でかえられます。 PCのせっていがめん（すまほでもおなじみえかたです） たっぷでかくだい"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"session","n":"セッション表示","dv":"","k":"時間とイベント 経済指標と市場の時間 オフ セッション表示（アラート） 表示 セッション：通知タイミング 経済指標・セッション表示","w":"ロンドン市場とニューヨーク市場が始まる時間に、縦の線を引く機能です。市場が始まると値動きが大きくなりやすいので、その時間が分かるようにします。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」を開く 「セッション表示」にチェックを入れる（始まる前にお知らせがほしいときは「アラート」にも） お知らせは、市場が始まる5分前に届きます（最初の値） その時間からトレードを始める、逆にその時間を避ける、といった使い方ができます","nr":"せっしょんひょうじ","kr":"じかんといべんと けいざいしひょうとしじょうのじかん おふ せっしょんひょうじ（あらーと） ひょうじ せっしょん：つうちたいみんぐ けいざいしひょう・せっしょんひょうじ","wr":"ろんどんしじょうとにゅーよーくしじょうがはじまるじかんに、たてのせんをひくきのうです。しじょうがはじまるとあたいうごきがおおきくなりやすいので、そのじかんがわかるようにします。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」をひらく 「せっしょんひょうじ」にちぇっくをいれる（はじまるまえにおしらせがほしいときは「あらーと」にも） おしらせは、しじょうがはじまる5ふんまえにとどきます（さいしょのあたい） そのじかんからとれーどをはじめる、ぎゃくにそのじかんをさける、といったつかいかたができます"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"scalp","n":"スキャモード","dv":"","k":"見やすさ チャートを見やすくする オフ スキャモード 表示","w":"スキャルピング（数分〜数十分の短い売買）をしやすい表示に切り替える機能です。","t":"チャートの右上に、時間足ごとのトレンドの向き（M15 のチャートなら M15・M5、H4 なら H4・H1 の矢印）、足が確定するまでの残り時間（01:49 など）、スプレッド（sp）が出ます（PCの画像の右は、この表示を拡大したものです） チャートの上と下に「値幅感」の線が出ます（値動きの幅の目安） 右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」 でオンにします","nr":"すきゃもーど","kr":"みやすさ ちゃーとをみやすくする おふ すきゃもーど ひょうじ","wr":"すきゃるぴんぐ（すうふん〜すうじゅっぷんのみじかいばいばい）をしやすいひょうじにきりかえるきのうです。","tr":"ちゃーとのみぎうえに、じかんあしごとのとれんどのむき（M15 のちゃーとなら M15・M5、H4 なら H4・H1 のやじるし）、あしがかくていするまでののこりじかん（01:49 など）、すぷれっど（sp）がでます（PCのがぞうのみぎは、このひょうじをかくだいしたものです） ちゃーとのあがとしたに「ねはばかん」のせんがでます（あたいうごきのはばのめやす） みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」 でおんにします"},{"f":"ytt-web-f-chart.html","pt":"チャートの表示","no":"4","id":"watermark","n":"通貨ペア・時間足をすかし表示","dv":"","k":"見やすさ チャートを見やすくする オン 通貨ペア・時間足をすかし表示 表示","w":"チャートの背景に、いま見ている通貨ペアと時間足を、大きく薄く表示する機能です。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」を開く 「通貨ペア・時間足をすかし表示」にチェックを入れる（外すと消えます） 最初からオンです 「XAUUSD M15」のように、チャートのまん中に大きく薄く出ます。いまどの通貨ペア・時間足を見ているか、ひと目で分かります","nr":"つうかぺあ・じかんあしをすかしひょうじ","kr":"みやすさ ちゃーとをみやすくする おん つうかぺあ・じかんあしをすかしひょうじ ひょうじ","wr":"ちゃーとのはいけいに、いまみているつうかぺあとじかんあしを、おおきくうすくひょうじするきのうです。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」をひらく 「つうかぺあ・じかんあしをすかしひょうじ」にちぇっくをいれる（はずすときえます） さいしょからおんです 「XAUUSD M15」のように、ちゃーとのまんなかにおおきくうすくでます。いまどのつうかぺあ・じかんあしをみているか、ひとめでわかります"},{"f":"ytt-web-f-tools.html","pt":"分析ツール","no":"5","id":"calendar","n":"損益カレンダー","dv":"","k":"振り返り 損益カレンダー ","w":"日ごとの損益を、カレンダーの形で見られる画面です。勝った日は緑、負けた日は赤の色がつくので、自分の調子がひと目で分かります。これまでの「トレードノート」のように、自分のトレードを数字で振り返れます。","t":"PCは画面の右端にある、カレンダーのアイコンを押す。スマホは下のメニューの「ツール」から「損益カレンダー」を開く ‹ › で見たい月を選ぶ 上の段：その月の損益、トレードの回数、勝った日と負けた日の数 プロフィットファクター：総利益 ÷ 総損失。1より大きければ、利益が出ています 右端：週ごとの損益と、勝ち（W）・負け（L）の日数 PCは、日付を押すと、その日のトレードの明細が開きます 日付の区切りは、日本時間ではなく証券会社のサーバーの時間です。日をまたぐころのトレードは、日本時間の日付とずれることがあります","nr":"そんえきかれんだー","kr":"ふりかえり そんえきかれんだー ","wr":"にちごとのそんえきを、かれんだーのかたちでみられるがめんです。かったにちはみどり、まけたにちはあかのいろがつくので、じぶんのちょうしがひとめでわかります。これまでの「とれーどのーと」のように、じぶんのとれーどをすうじでふりかえれます。","tr":"PCはがめんのみぎはしにある、かれんだーのあいこんをおす。すまほはしたのめにゅーの「つーる」から「そんえきかれんだー」をひらく ‹ › でみたいがつをえらぶ うえのだん：そのがつのそんえき、とれーどのかいすう、かったにちとまけたにちのかず ぷろふぃっとふぁくたー：そうりえき ÷ そうそんしつ。1よりおーきければ、りえきがでています みぎはし：しゅうごとのそんえきと、かち（W）・まけ（L）のにっすう PCは、ひづけをおすと、そのにちのとれーどのめいさいがひらきます ひづけのくぎりは、にほんじかんではなくしょうけんがいしゃのさーばーのじかんです。にちをまたぐころのとれーどは、にほんじかんのひづけとずれることがあります"},{"f":"ytt-web-f-tools.html","pt":"分析ツール","no":"5","id":"strength","n":"通貨強弱","dv":"","k":"相場の分析 通貨の強さと動き ","w":"8つの通貨（ドル・円・ユーロ・ポンドなど）のうち、いまどれが強くて、どれが弱いかを比べられる画面です。","t":"PCは画面の右端にある、折れ線グラフのアイコンを押す。スマホは下のメニューの「ツール」から「通貨強弱」を開く 「1日」「週間」「月間」から期間を選ぶ 上のグラフ：期間のはじめを0として、それぞれの通貨がどう動いたか 下の横棒：期間全体での強さ。右の数字がプラスなら強く、マイナスなら弱い（棒が長いほど、大きく動いています） 強い通貨を買って、弱い通貨を売る組み合わせを探すのに使えます ドルストレート（EURUSDなど、ドルとの組み合わせ）の1時間足から計算しています。対象はUSD・JPY・EUR・GBP・AUD・NZD・CAD・CHFの8通貨です。","nr":"つうかきょうじゃく","kr":"そうばのぶんせき つうかのつよさとうごき ","wr":"8つのつうか（どる・えん・ゆーろ・ぽんどなど）のうち、いまどれがつよくて、どれがよわいかをくらべられるがめんです。","tr":"PCはがめんのみぎはしにある、おれせんぐらふのあいこんをおす。すまほはしたのめにゅーの「つーる」から「つうかきょうじゃく」をひらく 「1にち」「しゅうかん」「げっかん」からきかんをえらぶ うえのぐらふ：きかんのはじめを0として、それぞれのつうかがどううごいたか したのよこぼう：きかんぜんたいでのつよさ。みぎのすうじがぷらすならつよく、まいなすならよわい（ぼうがながいほど、おおきくうごいています） つよいつうかをかって、よわいつうかをうるくみあわせをさがすのにつかえます どるすとれーと（EURUSDなど、どるとのくみあわせ）の1じかんあしからけいさんしています。たいしょうはUSD・JPY・EUR・GBP・AUD・NZD・CAD・CHFの8つうかです。"},{"f":"ytt-web-f-tools.html","pt":"分析ツール","no":"5","id":"heatmap","n":"ヒートマップ","dv":"","k":"相場の分析 通貨の強さと動き ","w":"8つの通貨どうしが、どれくらい動いたかを、色つきの表で見られる画面です。","t":"PCは画面の右端にある、四角が4つのアイコンを押す。スマホは下のメニューの「ツール」から「ヒートマップ」を開く 「1日」「週間」「月間」から期間を選ぶ 左の通貨が、上の通貨に対してどれだけ動いたかを表します 緑はプラス、赤はマイナス。色がはっきりしているほど、大きく動いています","nr":"ひーとまっぷ","kr":"そうばのぶんせき つうかのつよさとうごき ","wr":"8つのつうかどうしが、どれくらいうごいたかを、いろつきのおもてでみられるがめんです。","tr":"PCはがめんのみぎはしにある、しかくが4つのあいこんをおす。すまほはしたのめにゅーの「つーる」から「ひーとまっぷ」をひらく 「1にち」「しゅうかん」「げっかん」からきかんをえらぶ ひだりのつうかが、うえのつうかにたいしてどれだけうごいたかをあらわします みどりはぷらす、あかはまいなす。いろがはっきりしているほど、おおきくうごいています"},{"f":"ytt-web-f-tools.html","pt":"分析ツール","no":"5","id":"news","n":"ニュース","dv":"","k":"ニュース ニュースと利確速報  ニュースを上部に表示（PC） 表示","w":"為替のニュースを、一覧で読める画面です。重要度（中・重要）がつくので、大事なニュースを見逃しません。","t":"PCは画面の右端にある、新聞のアイコンを押す（PCの画像の右端の赤い枠）。スマホは下のメニューの「ツール」から「ニュース」を開く 「〇〇関連」（表示中の通貨ペア）か「すべて」を選ぶ PCは、画面のいちばん上の帯にも、最新のニュースが流れます 上の帯にニュースを出す・出さないは、右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」 の「ニュースを上部に表示」で切り替えられます（PCだけの設定です）","nr":"にゅーす","kr":"にゅーす にゅーすとりかくそくほう  にゅーすをじょうぶにひょうじ（PC） ひょうじ","wr":"かわせのにゅーすを、いちらんでよめるがめんです。じゅうようど（なか・じゅうよう）がつくので、だいじなにゅーすをみのがしません。","tr":"PCはがめんのみぎはしにある、しんぶんのあいこんをおす（PCのがぞうのみぎはしのあかいわく）。すまほはしたのめにゅーの「つーる」から「にゅーす」をひらく 「〇〇かんれん」（ひょうじちゅうのつうかぺあ）か「すべて」をえらぶ PCは、がめんのいちばんうえのおびにも、さいしんのにゅーすがながれます うえのおびににゅーすをだす・ださないは、みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」 の「にゅーすをじょうぶにひょうじ」できりかえられます（PCだけのせっていです）"},{"f":"ytt-web-f-tools.html","pt":"分析ツール","no":"5","id":"takeprofit","n":"利確速報","dv":"","k":"ニュース ニュースと利確速報 トースト表示オン 利確速報をトースト表示 表示 利確速報を上部に表示（PC） 表示 利確をチャートに表示（表示数） 表示","w":"FX SPACEのメンバーが利確すると、その時刻・通貨ペア・金額が流れてくる機能です。","t":"PCは、画面のいちばん上のニュースの帯のすぐ下に、利確速報がいつも流れています（画像の赤い枠）。新しい利確が流れてくると、その枠が光ります 「利確速報をトースト表示」がオン（最初からオン）だと、「XAUUSD で +¥117,147 の利確がありました」のようなお知らせも出ます。PCは右下、スマホは画面の下に出ます スマホには上の帯がないので、このお知らせで届きます 上の帯の利確速報は、右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」 の「利確速報を上部に表示」で出さないようにもできます（PCだけの設定です） 「利確をチャートに表示（表示数）」（最初はオフ）をオンにすると、ほかのメンバーの利確の印がチャートに出ます（通貨ペアごとに、表示する数を決めます。最初は10件）","nr":"りかくそくほう","kr":"にゅーす にゅーすとりかくそくほう とーすとひょうじおん りかくそくほうをとーすとひょうじ ひょうじ りかくそくほうをじょうぶにひょうじ（PC） ひょうじ りかくをちゃーとにひょうじ（ひょうじかず） ひょうじ","wr":"FX SPACEのめんばーがりかくすると、そのじこく・つうかぺあ・きんがくがながれてくるきのうです。","tr":"PCは、がめんのいちばんうえのにゅーすのおびのすぐしたに、りかくそくほうがいつもながれています（がぞうのあかいわく）。あたらしいりかくがながれてくると、そのわくがひかります 「りかくそくほうをとーすとひょうじ」がおん（さいしょからおん）だと、「XAUUSD で +¥117,147 のりかくがありました」のようなおしらせもでます。PCはみぎした、すまほはがめんのしたにでます すまほにはうえのおびがないので、このおしらせでとどきます うえのおびのりかくそくほうは、みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」 の「りかくそくほうをじょうぶにひょうじ」でださないようにもできます（PCだけのせっていです） 「りかくをちゃーとにひょうじ（ひょうじかず）」（さいしょはおふ）をおんにすると、ほかのめんばーのりかくのいんがちゃーとにでます（つうかぺあごとに、ひょうじするかずをきめます。さいしょは10けん）"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"prop","n":"プロップモード","dv":"","k":"モード 口座に合わせたモード オフ プロップモード（初期残高） プロップモード 失格・合格ライン、強制SL移動など プロップモード 0時リセット基準・カスタム時刻・0時有効証拠金 プロップモード","w":"Fintokeiなどのプロップファーム（テストに合格すると、会社の資金でトレードできるサービス）で、ルール違反による失格を防ぐ機能です。合格ラインや失格ラインをチャートに表示し、損切りが1日の上限を超えないように自動で調整します。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「プロップモード」を開く 「プロップモード（初期残高）」にチェックを入れ、プランの初期資金を入れる 失格ラインなどの数値を、自分のプランのルールに合わせる ラインは、ポジションを持つと出ます 出るのは「プロップ:+8.0%」（合格）「プロップ:3%警告」「プロップ:-5.0%」（1日の上限）「プロップ:-10.0%」（全体の上限） SLが1日の損失の上限より遠くに置かれないよう、自動で動きます（強制SL移動） 項目 最初の値 どうなるか 失格ライン（初期残高比） 10% 全体の損失の上限。ここまで下がると失格 失格ライン（0時証拠金比） 5% 1日の損失の上限。その日の0時の有効証拠金から計算 合格ライン（初期残高比） 8% 合格の目標 強制SL移動（0時証拠金比） 4.5% SLがこれより遠くに置かれないように動かす 合格時強制利確（初期残高比） 8.1% 有効証拠金がここまで来ると、自動で全決済 3%警告ライン 3% 同時に持っているポジションの損失がここまで来ると、警告が出る（決済はしない） 0時リセット基準 Fintokei（日本時間9時） 1日の区切りの時刻。Fintokei（日本時間9時）・Fundora（日本時間6時／7時）・カスタム（時刻を指定）から選ぶ 0時有効証拠金（手動上書き） — 1日の損失の計算に使う金額を、手で入れる ご注意 数値は、自分のプランに合わせてください ルールはプロップファームやプランによって違います。","nr":"ぷろっぷもーど","kr":"もーど こうざにあわせたもーど おふ ぷろっぷもーど（しょきざんだか） ぷろっぷもーど しっかく・ごうかくらいん、きょうせいSLいどうなど ぷろっぷもーど 0ときりせっときじゅん・かすたむじこく・0ときゆうこうしょうこきん ぷろっぷもーど","wr":"Fintokeiなどのぷろっぷふぁーむ（てすとにごうかくすると、かいしゃのしきんでとれーどできるさーびす）で、るーるいはんによるしっかくをふせぐきのうです。ごうかくらいんやしっかくらいんをちゃーとにひょうじし、そんぎりりが1にちのじょうげんをこえないようにじどうでちょうせいします。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ぷろっぷもーど」をひらく 「ぷろっぷもーど（しょきざんだか）」にちぇっくをいれ、ぷらんのしょきしきんをいれる しっかくらいんなどのすうちを、じぶんのぷらんのるーるにあわせる らいんは、ぽじしょんをもつとでます でるのは「ぷろっぷ:+8.0%」（ごうかく）「ぷろっぷ:3%けいこく」「ぷろっぷ:-5.0%」（1にちのじょうげん）「ぷろっぷ:-10.0%」（ぜんたいのじょうげん） SLが1にちのそんしつのじょうげんよりとおくにおかれないよう、じどうでうごきます（きょうせいSLいどう） こうもく さいしょのあたい どうなるか しっかくらいん（しょきざんだかひ） 10% ぜんたいのそんしつのじょうげん。ここまでさがるとしっかく しっかくらいん（0ときしょうこきんひ） 5% 1にちのそんしつのじょうげん。そのにちの0ときのゆうこうしょうこきんからけいさん ごうかくらいん（しょきざんだかひ） 8% ごうかくのもくひょう きょうせいSLいどう（0ときしょうこきんひ） 4.5% SLがこれよりとおくにおかれないようにうごかす ごうかくじきょうせいりかく（しょきざんだかひ） 8.1% ゆうこうしょうこきんがここまでくると、じどうでぜんけっさい 3%けいこくらいん 3% どうじにもっているぽじしょんのそんしつがここまでくると、けいこくがでる（けっさいはしない） 0ときりせっときじゅん Fintokei（にほんじかん9とき） 1にちのくぎりのじこく。Fintokei（にほんじかん9とき）・Fundora（にほんじかん6とき／7とき）・かすたむ（じこくをしてい）からえらぶ 0ときゆうこうしょうこきん（しゅどううわかき） — 1にちのそんしつのけいさんにつかうきんがくを、てでいれる ごちゅうい すうちは、じぶんのぷらんにあわせてください るーるはぷろっぷふぁーむやぷらんによってちがいます。"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"virtual","n":"仮想残高モード","dv":"","k":"モード 口座に合わせたモード オフ 仮想残高モード プロップモード","w":"プロップモード中に、「失格になるまでに使える金額」を残高とみなして、ロットを計算する機能です。負けが続くとロットが自動で小さくなるので、失格しにくくなります。","t":"プロップモードをオンにする 右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「プロップモード」の「仮想残高モード」にチェックを入れる オンにすると、右上の残高が「仮想残高」の表示に変わります スマホでも、PCと同じ見た目です 例：初期残高5,000万円（失格ライン10%）で、いまの残高が4,900万円なら、500万円＋（−100万円）＝400万円を残高としてロットを計算します 仮想残高は、「失格までに使える金額」に「これまでの損益」を足した金額です。初期残高5,000万円（失格ライン10%）で、いまの残高が4,900万円なら、次のようになります。 失格までに使える金額 500万円 ＋ これまでの損益 −100万円 ＝ 仮想残高 400万円","nr":"かそうざんだかもーど","kr":"もーど こうざにあわせたもーど おふ かそうざんだかもーど ぷろっぷもーど","wr":"ぷろっぷもーどなかに、「しっかくになるまでにつかえるきんがく」をざんだかとみなして、ろっとをけいさんするきのうです。まけがつづくとろっとがじどうでちーさくなるので、しっかくしにくくなります。","tr":"ぷろっぷもーどをおんにする みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ぷろっぷもーど」の「かそうざんだかもーど」にちぇっくをいれる おんにすると、みぎうえのざんだかが「かそうざんだか」のひょうじにかわります すまほでも、PCとおなじみためです れい：しょきざんだか5,000まんえん（しっかくらいん10%）で、いまのざんだかが4,900まんえんなら、500まんえん＋（−100まんえん））400まんえんをざんだかとしてろっとをけいさんします かそうざんだかは、「しっかくまでにつかえるきんがく」に「これまでのそんえき」をたしたきんがくです。しょきざんだか5,000まんえん（しっかくらいん10%）で、いまのざんだかが4,900まんえんなら、つぎのようになります。 しっかくまでにつかえるきんがく 500まんえん ＋ これまでのそんえき −100まんえん   かそうざんだか 400まんえん"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"copy","n":"コピーモード（受信）","dv":"","k":"モード 口座に合わせたモード オフ コピーモード（受信） コピーモード 許容遅延時間 コピーモード コピー時のロット計算モード コピーモード","w":"コピーを 受け取る側 の口座で使う機能です。コピー元の口座でWeb版YTTからエントリーすると、同じポジションがこの口座にも入ります。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「コピーモード」を開く 「コピーモード（受信）」にチェックを入れ、案内に従ってコピー元の口座を選ぶ 「コピー時のロット計算モード」を選ぶ（損失率固定／損失額固定／ロット残高固定） スマホでも、PCと同じ見た目です コピーされるのは、コピー元でWeb版YTTからエントリーしたポジションだけです オンにしてコピー元を確定した時点で、この口座の保有中のポジションはすべて決済され、予約（指値・逆指値）はすべて取り消されます コピーされるのは、新規エントリー（成行と、約定した指値・逆指値）、全決済・部分決済、SL・TPの変更です。追加ポジは、この口座のロットにコピー元と同じ倍率をかけて入ります この口座でポジションを手で決済すると、そのポジションはそれ以降コピーされません コピー元のエントリーから「許容遅延時間」（最初は5.0秒）より時間がたっていたら、そのエントリーはコピーされません コピー元の口座で、登録などの準備はいりません（同じDiscordのログインのほかの口座から選ぶだけです） 設定の画面では、上の「コピーモード（受信）」でコピー元の口座を選び、下の「コピー時のロット計算モード」で、自分の口座でのロットの決め方を選びます。コピー中のルールは、その下の表のとおりです。 設定 × 一般 キャンバス 配色 コピーモード ☆ コピーモード(受信) 未選択 ☆ 許容遅延時間 − 5.0 秒 ＋ コピー時のロット計算モード ☆ 損失率固定 − 2.0 % ＋ ☆ 損失額固定 − ¥5000 ＋ ☆ ロット残高固定 − 10万円：0.10 lot ＋ 設定方法 設定 → コピーモード（受信）をオン コピー元の口座設定画面が出るので、案内に従って設定。「コピー時のロット計算モード」も確認 新規エントリー コピー以外はできない TP / SL の移動 できない コピーされる Web版YTTからのエントリーのみ コピー元が他の方法で建てたポジションはコピーされません ロット ロット計算モードに従う 損失率固定・損失額固定のときは、SLが無いポジションはコピーされません TP / SL 同じ幅でコピー 約定価格の差を吸収するため、コピー元と同じTP/SL幅になるように設定されます オンにした後 Web版の画面は閉じてOK 連携ツールを入れた取引ツールは起動したままにしてください","nr":"こぴーもーど（じゅしん）","kr":"もーど こうざにあわせたもーど おふ こぴーもーど（じゅしん） こぴーもーど きょようちえんじかん こぴーもーど こぴーときのろっとけいさんもーど こぴーもーど","wr":"こぴーを うけとるがわ のこうざでつかうきのうです。こぴーもとのこうざでWebはんYTTからえんとりーすると、おなじぽじしょんがこのこうざにもいります。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「こぴーもーど」をひらく 「こぴーもーど（じゅしん）」にちぇっくをいれ、あんないにしたがってこぴーもとのこうざをえらぶ 「こぴーときのろっとけいさんもーど」をえらぶ（そんしつりつこてい／そんしつひたいこてい／ろっとざんだかこてい） すまほでも、PCとおなじみためです こぴーされるのは、こぴーもとでWebはんYTTからえんとりーしたぽじしょんだけです おんにしてこぴーもとをかくていしたじてんで、このこうざのほゆうなかのぽじしょんはすべてけっさいされ、よやく（さしね・ぎゃくさしね）はすべてとりけされます こぴーされるのは、しんきえんとりー（なりゆきと、やくじょうしたさしね・ぎゃくさしね）、ぜんけっさい・ぶぶんけっさい、SL・TPのへんこうです。ついかぽじは、このこうざのろっとにこぴーもととおなじばいりつをかけていります このこうざでぽじしょんをてでけっさいすると、そのぽじしょんはそれいこうこぴーされません こぴーもとのえんとりーから「きょようちえんじかん」（さいしょは5.0びょう）よりじかんがたっていたら、そのえんとりーはこぴーされません こぴーもとのこうざで、とうろくなどのじゅんびはいりません（おなじDiscordのろぐいんのほかのこうざからえらぶだけです） せっていのがめんでは、うえの「こぴーもーど（じゅしん）」でこぴーもとのこうざをえらび、したの「こぴーときのろっとけいさんもーど」で、じぶんのこうざでのろっとのきめかたをえらびます。こぴーなかのるーるは、そのしたのおもてのとおりです。 せってい × いっぱん きゃんばす はいしょく こぴーもーど ☆ こぴーもーど(じゅしん) みせんたく ☆ きょようちえんじかん − 5.0 びょう ＋ こぴーときのろっとけいさんもーど ☆ そんしつりつこてい − 2.0 % ＋ ☆ そんしつひたいこてい − ¥5000 ＋ ☆ ろっとざんだかこてい − 10まんえん：0.10 lot ＋ せっていほうほう せってい → こぴーもーど（じゅしん）をおん こぴーもとのこうざせっていがめんがでるので、あんないにしたがってせってい。「こぴーときのろっとけいさんもーど」もかくにん しんきえんとりー こぴーいがいはできない TP / SL のいどう できない こぴーされる WebはんYTTからのえんとりーのみ こぴーもとがほかのほうほうでたてたぽじしょんはこぴーされません ろっと ろっとけいさんもーどにしたがう そんしつりつこてい・そんしつひたいこていのときは、SLがないぽじしょんはこぴーされません TP / SL おなじはばでこぴー やくじょうかかくのさをきゅうしゅうするため、こぴーもととおなじTP/SLはばになるようにせっていされます おんにしたのち WebはんのがめんはとじてOK れんけいつーるをいれたとりひきつーるはきどうしたままにしてください"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"pl-hide","n":"損益非表示","dv":"","k":"見た目 画面の見た目を変える オフ 損益非表示 表示","w":"画面の金額を隠す機能です。金額が大きくなると、あせっていつもと違うトレードをしてしまうことがあります。そんなときに、金額を気にせずトレードするための機能です。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」 でオンにします オンにすると、 残高・有効証拠金・許容損失 が「— — —」になります 持っているポジションの損益も「----」になります （決済するまで、勝っているか負けているかは分かりません） PCの画像は、左が残高と有効証拠金、右が保有中ポジションの損益です PCは、最初から「お気に入り」（★）に入っているので、右のパネルからすぐ切り替えられます","nr":"そんえきひひょうじ","kr":"みため がめんのみためをかえる おふ そんえきひひょうじ ひょうじ","wr":"がめんのきんがくをかくすきのうです。きんがくがおおきくなると、あせっていつもとちがうとれーどをしてしまうことがあります。そんなときに、きんがくをきにせずとれーどするためのきのうです。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」 でおんにします おんにすると、 ざんだか・ゆうこうしょうこきん・きょようそんしつ が「— — —」になります もっているぽじしょんのそんえきも「----」になります （けっさいするまで、かっているかまけているかはわかりません） PCのがぞうは、ひだりがざんだかとゆうこうしょうこきん、みぎがほゆうなかぽじしょんのそんえきです PCは、さいしょから「おきにいり」（★）にいっっているので、みぎのぱねるからすぐきりかえられます"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"bonus","n":"残高にボーナスを含めて表示","dv":"","k":"見た目 画面の見た目を変える オフ 残高にボーナスを含めて表示 表示","w":"口座のボーナスを、残高に含めて表示する設定です。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、「一般」の「表示」 でオンにします この設定で変わるのは表示だけです アップデート予定 ロットの計算にボーナスを含めるかどうかの設定が、連携ツール（EA）からWeb版YTTの設定に移ります","nr":"ざんだかにぼーなすをふくめてひょうじ","kr":"みため がめんのみためをかえる おふ ざんだかにぼーなすをふくめてひょうじ ひょうじ","wr":"こうざのぼーなすを、ざんだかにふくめてひょうじするせっていです。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、「いっぱん」の「ひょうじ」 でおんにします このせっていでかわるのはひょうじだけです あっぷでーとよてい ろっとのけいさんにぼーなすをふくめるかどうかのせっていが、れんけいつーる（EA）からWebはんYTTのせっていにうつります"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"theme","n":"配色","dv":"","k":"見た目 画面の見た目を変える ","w":"画面全体の色と質感を、好みに合わせて変えられる設定です。","t":"右下の歯車（スマホは「設定」）を押し、「配色」のタブを開く 「素材」と「配色」を選ぶ 素材 ：マット（枠のない一枚板の質感）／ガラス（カードや浮いているパネルだけが質感を持つ） 配色 ：標準（紫）／ダーク（グレー）／ライト（白が基調で、明るい場所で見やすい） 配色を変えると、チャートの色も一緒に変わります（キャンバスで自分で変えた色は、そのまま残ります） アップデート予定 配色の種類が増えます","nr":"はいしょく","kr":"みため がめんのみためをかえる ","wr":"がめんぜんたいのいろとしつかんを、このみにあわせてかえられるせっていです。","tr":"みぎしたのはぐるま（すまほは「せってい」）をおし、「はいしょく」のたぶをひらく 「そざい」と「はいしょく」をえらぶ そざい ：まっと（わくのないいちまいいたのしつかん）／がらす（かーどやういているぱねるだけがしつかんをもつ） はいしょく ：ひょうじゅん（むらさき）／だーく（ぐれー）／らいと（しろがきちょうで、あかるいばしょでみやすい） はいしょくをかえると、ちゃーとのいろもいっしょにかわります（きゃんばすでじぶんでかえたいろは、そのままのこります） あっぷでーとよてい はいしょくのしゅるいがふえます"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"canvas","n":"キャンバス（チャートの色）","dv":"","k":"見た目 画面の見た目を変える ","w":"ローソク足やチャートの背景の色など、チャートの見た目を細かく変えられる設定です。","t":"右下の歯車（スマホは「設定」）→「キャンバス」のタブで変えます ローソク足（上昇・下降）、背景、グリッド、十字カーソルの色を選べます 「期間区切りライン」をオンにすると、日の区切り（0時）に縦の線が出ます（日足・週足・月足では出ません）","nr":"きゃんばす（ちゃーとのいろ）","kr":"みため がめんのみためをかえる ","wr":"ろーそくあしやちゃーとのはいけいのいろなど、ちゃーとのみためをこまかくかえられるせっていです。","tr":"みぎしたのはぐるま（すまほは「せってい」）→「きゃんばす」のたぶでかえます ろーそくあし（じょうしょう・かこう）、はいけい、ぐりっど、じゅうじかーそるのいろをえらべます 「きかんくぎりらいん」をおんにすると、にちのくぎり（0とき）にたてのせんがでます（ひあし・しゅうあし・つきあしではでません）"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"open","n":"設定を開く","dv":"","k":"設定画面 設定画面の使い方 ","w":"Web版YTTの細かい設定を変える画面です。「一般」「キャンバス」「配色」の3つのタブがあります。","t":"PCは右下の歯車、スマホは下のメニューの「設定」を押す タブを選んで、項目を変える 変えた設定は、この口座にそのまま残ります（ 初期値にリセット で元に戻せます）","nr":"せっていをひらく","kr":"せっていがめん せっていがめんのつかいかた ","wr":"WebはんYTTのこまかいせっていをかえるがめんです。「いっぱん」「きゃんばす」「はいしょく」の3つのたぶがあります。","tr":"PCはみぎしたのはぐるま、すまほはしたのめにゅーの「せってい」をおす たぶをえらんで、こうもくをかえる かえたせっていは、このこうざにそのままのこります（ しょきちにりせっと でもとにもどせます）"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"sync","n":"PCとスマホで共通のもの・別々のもの","dv":"","k":"設定画面 設定画面の使い方 ","w":"Web版YTTは、PCとスマホの両方で使えます。PCとスマホで共通になるものと、端末ごとに別々のものがあります。","t":"スマホで口座が変わらないときは ：PCとスマホは、それぞれ別に口座を選びます。スマホでも口座番号を押して、使う口座を選んでください（ 口座を切り替える ） ほかの口座にも同じ設定を使いたいときは、 他の口座に設定をコピー を使います","nr":"PCとすまほできょうつうのもの・べつべつのもの","kr":"せっていがめん せっていがめんのつかいかた ","wr":"WebはんYTTは、PCとすまほのりょうほうでつかえます。PCとすまほできょうつうになるものと、たんまつごとにべつべつのものがあります。","tr":"すまほでこうざがかわらないときは ：PCとすまほは、それぞれべつにこうざをえらびます。すまほでもこうざばんごうをおして、つかうこうざをえらんでください（ こうざをきりかえる ） ほかのこうざにもおなじせっていをつかいたいときは、 ほかのこうざにせっていをこぴー をつかいます"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"fav","n":"お気に入り（☆）","dv":"","k":"設定画面 設定画面の使い方 ","w":"よく使う設定を、右のパネルからすぐにオン・オフできるようにする機能です。","t":"設定画面で、項目の左の☆を押す（黄色の★になります） 右のパネルのいちばん下の「お気に入り」に、その項目が並ぶ 右のパネルから、設定画面を開かずにオン・オフできます","nr":"おきにいり（☆）","kr":"せっていがめん せっていがめんのつかいかた ","wr":"よくつかうせっていを、みぎのぱねるからすぐにおん・おふできるようにするきのうです。","tr":"せっていがめんで、こうもくのひだりの☆をおす（きいろの★になります） みぎのぱねるのいちばんしたの「おきにいり」に、そのこうもくがならぶ みぎのぱねるから、せっていがめんをひらかずにおん・おふできます"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"copy-settings","n":"他の口座に設定をコピー","dv":"","k":"設定画面 設定画面の使い方 ","w":"いまの口座の設定を、ほかの口座にもまとめてコピーする機能です。複数の口座を使っている人に便利です。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、いちばん下の「他の口座に設定をコピー」を押す コピー先の口座を選んで、「確定」を押す 「設定をコピーしますか？」と出たら、「実行」を押す ロットの決め方（ロット計算モード）や、コピーモードの設定も、いっしょにコピーされます コピー先の口座にもともと入っていた設定は、上書きされます スマホも、設定画面のいちばん下に同じボタンがあります","nr":"ほかのこうざにせっていをこぴー","kr":"せっていがめん せっていがめんのつかいかた ","wr":"いまのこうざのせっていを、ほかのこうざにもまとめてこぴーするきのうです。ふくすうのこうざをつかっているにんにべんりです。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、いちばんしたの「ほかのこうざにせっていをこぴー」をおす こぴーさきのこうざをえらんで、「かくてい」をおす 「せっていをこぴーしますか？」とでたら、「じっこう」をおす ろっとのきめかた（ろっとけいさんもーど）や、こぴーもーどのせっていも、いっしょにこぴーされます こぴーさきのこうざにもともといっっていたせっていは、うわかきされます すまほも、せっていがめんのいちばんしたにおなじぼたんがあります"},{"f":"ytt-web-f-settings.html","pt":"モードと設定","no":"6","id":"reset","n":"初期値にリセット","dv":"","k":"設定画面 設定画面の使い方 ","w":"設定をすべて、最初の状態に戻す機能です。","t":"右下の歯車（スマホは下のメニューの「設定」）を押し、いちばん下の「初期値にリセット」を押す 「初期値にリセットしますか？」と出たら、「実行」を押す この口座の設定が、すべて最初の値に戻ります。元に戻すことはできません リセットすると、ページが自動で読み込み直されます スマホも、設定画面のいちばん下に同じボタンがあります","nr":"しょきちにりせっと","kr":"せっていがめん せっていがめんのつかいかた ","wr":"せっていをすべて、さいしょのじょうたいにもどすきのうです。","tr":"みぎしたのはぐるま（すまほはしたのめにゅーの「せってい」）をおし、いちばんしたの「しょきちにりせっと」をおす 「しょきちにりせっとしますか？」とでたら、「じっこう」をおす このこうざのせっていが、すべてさいしょのあたいにもどります。もとにもどすことはできません りせっとすると、ぺーじがじどうでよみこみなおされます すまほも、せっていがめんのいちばんしたにおなじぼたんがあります"}];
